# 🔴 01.09 · БЕШЕ «точно ЕДНА бариера». ТЕСТЪТ МЕ ХВАНА, когато добавих
# втора — и това е добра новина: значи този пазач НЕ е от 41-те, които
# преписват правилото. Но мярката му беше грешна.
# ЗАЩО СЕ МЕНИ: опасното нещо е бариера в СРЕДАТА на файла (ОДИТ-3, 29.07:
# гейтът стоеше на ред 354, П5/П6 идваха след него → червено = зелено CI).
# Опасен е МЯСТОТО, не БРОЯТ. А втора бариера НАЙ-ДОЛУ е точно лекът за
# новия дефект: П36 стои на ред ~7400 и не вижда 164-те проверки след него.
# «Точно една» забраняваше поправката, вместо да пази от дефекта.
# НОВАТА Е ПО-СТРОГА, НЕ ПО-СЛАБА: старата допускаше една бариера където и
# да е; новата иска ВСЯКА от тях да е след последния ck(). Мръдне ли една
# нагоре — пада. Плюс изрична долна граница на БРОЯ, за да не може някой да
# махне бариерата и проверката пак да е зелена.
_поз_бариери = [_и for _и in range(len(_selfsrc)) if _selfsrc.startswith(_EXIT, _и)]
_посл_ck = _selfsrc.rindex('ck("')
ck("О3 бариерите са поне ДВЕ (общият брой се пази най-долу)",
   len(_поз_бариери) >= 2)
ck(f"О3 ВСЯКА бариера е след последния тест ({len(_поз_бариери)} бр.)",
   bool(_поз_бариери) and min(_поз_бариери) > _посл_ck)
# и обратната посока: проверката трябва да МОЖЕ да падне
ck("О3 сравнението за бариерите е истинско, не тавтология",
   not (0 > _посл_ck))
ck("О3 финалният печат е накрая", _selfsrc.rindex(_GREEN) > _selfsrc.rindex('ck("'))
ck("О3 смяна на класа → НОВ ключ", _bk(_b1) != _bk([("1час", "short", "strong"), ("4час", "short", "premium")]))

