# П7 · ОДИТ-6 (04.08): СЯНКАТА КРИЕШЕ ПРИБРАНИТЕ ТЕЙК-ПРОФИТИ.
# `_exit_msg` имаше сметка по стълбата 1/3, `_shadow_exit_msg` НЯМАШЕ →
# безрисков стоп след ТП1+ТП2 се показваше «+0.00$», а стълбата дава +6.50$.
# Мерено в live/sent_log.jsonl: 4 карти, скрити +22.00$/oz. Собственикът е
# виждал САМО сянка-карти (реални сделки: 0 за 387 ръна) → само счупените.
# ═══════════════════════════════════════════════════════════════════════
_E = 4000.0
# 🔴 02.09 · НИВАТА ИДВАТ ОТ `_levels`, не са заковани. Бяха 7.5/12/20 —
# старата шорт геометрия. След като шортът получи 50/100/200 с дялове ½¼¼,
# закованите нива щяха да се смесят с новите дялове (½·7.5 + ¼·12 = 6.75
# вместо очакваните 6.50) — тест, който мери СМЕС от две машини.
# Сега нивата и дяловете идват от ЕДИН източник, а очакваните числа се
# СМЯТАТ от него (виж `_оч11` по-долу).
_LVs = dict(lb._levels(_E, "short"), sl=_E)
_Д11 = lb._геом("short")[2]                       # дяловете на шорта
def _оч11(*взети):
    """очакваната сметка по стълбата, СМЯТАНА от геометрията"""
    _т = lb._геом("short")[0]
    return sum(_Д11[i] * _т[i] for i in range(3) if i in взети)


def _shtr(hit):
    return {"direction": "short", "entry": _E, "levels": _LVs, "hit": dict(hit),
            "sym": "XAUUSD", "opened": "2026-08-03T00:00:00", "shadow": True}


