# --- 6 · САМОТО dd20: от ЗАВЪРШЕНИ дни, прозорецът включва последното затваряне ---
_c19 = pd.Series([100.0] * 19 + [110.0] + [99.0],
                 index=pd.date_range("2026-01-01", periods=21, freq="D"))
