import re as _re39
# ═══ П39 · О2 · «МАЛЪК РАЗМЕР» ВЕЧЕ ИМА ЧИСЛО ЗАД СЕБЕ СИ (ОДИТ-38) ════════
# 🔴 Доказано преди фикса: застоял сигнал даваше 0.05 лот / ≈$100 — ТОЧНО
# колкото пресен, макар присъдата да казва «ДА (малък размер)». Думата
# обещаваше намаление, което кодът не правеше.
# О2(а): «риск $27» не казва нищо, ако не знаеш от колко. При среброто мин.
# лот е 50 унции — при малък баланс това е далеч над целевия процент.
def _р39(streak, **кв):
    _т, _ok = lb._advice_entry("long", streak, stats, None, False, 0)
    _m = lb._sig_msg("long", 6, 5, "СИЛЕН", {"mid": 4365.2}, 4365.0, "x",
                     lb._levels(4365.2, "long"), 4365.2, _т,
                     {"долар": True, "лихви": True}, streak, {"vol_rank": .35},
                     stats, 5000, 2.0, adv_ok=_ok, **кв)
    return _re39.sub(r"<[^>]+>", "", _m)
_пресен39, _застоял39 = _р39(1), _р39(5)
# 🔴 01.09 · ВЪРЗАН ЗА МНОЖИТЕЛЯ. Дотук изискваше присъдата ВИНАГИ да обещава
# «малък размер» — вярно, докато `МАЛЪК_РАЗМЕР_W` беше 0.5. Собственикът го
# отпуши на 1.0; тогава обещанието щеше да е ЛЪЖА (същият ОДИТ-38 наопаки).
# Сега проверката работи и в двете посоки: думата съществува ТОЧНО когато
# множителят реже.
ck("П39 присъдата обещава «малък размер» само когато множителят реже",
   ("малък размер" in lb._advice_entry("long", 5, stats, None, False, 0)[0])
   == (lb.МАЛЪК_РАЗМЕР_W < 0.999))
# ОДИТ-41 · лотът падна; остана препоръката с думи. Тя пак е РАЗЛИЧНА
# между пресен и застоял сигнал — това беше същината на О2(в).
# 🔴 ОБНОВЕН 18.08 · «малък размер» стана СТЪЛБИЦА от четири нива + ДЯЛ.
# Същината на О2(в) остава: думата трябва да е РАЗЛИЧНА между пресен и
# застоял, тоест да има число зад себе си. Сега се пази по-силното —
# двата случая дават различен РЕД, и застоялият е с по-малък дял.
_рз39 = lambda т: [x for x in т.split(chr(10)) if "размер:" in x]
# 🔴 01.09 · СЪЩОТО. При отпушен множител застоял и пресен ПО ПРАВО дават
# един и същ ред — това е смисълът на отпушването, не дефект.
ck("П39 застоялият се различава от пресния ТОЧНО когато множителят реже",
   bool(_рз39(_застоял39)) and bool(_рз39(_пресен39))
   and ((_рз39(_застоял39)[0] != _рз39(_пресен39)[0]) == (lb.МАЛЪК_РАЗМЕР_W < 0.999)))
ck("П39 картата казва ЗАЩО — само когато има какво да обясни",
   ("сигналът не е пресен" in _застоял39) == (lb.МАЛЪК_РАЗМЕР_W < 0.999))
ck("П39 при пресен сигнал НЯМА намаление", "пълен размер" in _пресен39)
# 🔴 01.09 · ОБЪРНАТ ЗАЕДНО С МНОЖИТЕЛЯ. Дотук изискваше застоялият сигнал да
# показва ДЯЛ («от пълния») — вярно, докато `МАЛЪК_РАЗМЕР_W` беше 0.5.
# Собственикът го отпуши на 1.0, значи застоялият вече НЕ се реже и «пълен
# размер» е ВЯРНОТО. Тестът не се трие — сменя се на това, което ВИНАГИ е бил
# истинският му смисъл: ДУМАТА И ЧИСЛОТО ДА СЕ СЪГЛАСЯВАТ.
_дял39 = "от пълния" in _застоял39
_пълен39 = "пълен размер" in _застоял39
ck("П39 думата за размера СЪОТВЕТСТВА на множителя",
   (_дял39 and not _пълен39) if lb.МАЛЪК_РАЗМЕР_W < 0.999 else (_пълен39 and not _дял39))
# 🔴 И БЛИЗНАКЪТ: присъдата НЕ бива да обещава «малък размер», щом няма такъв
_прис39 = lb._advice_entry("long", 5, stats, None, False, 0)[0]
ck("П39 присъдата НЕ обещава намаление, което го няма",
   ("малък размер" in _прис39) == (lb.МАЛЪК_РАЗМЕР_W < 0.999))
ck("П39 картата не изброява повод, който не реже",
   ("сигналът не е пресен" in _застоял39) == (lb.МАЛЪК_РАЗМЕР_W < 0.999))

# ═══ П117 · И ЧЕТИРИТЕ МНОЖИТЕЛЯ СЕ НАЗОВАВАТ ════════════════════════════
# 🔴 01.09 · Размерът е ПРОИЗВЕДЕНИЕ от четири числа (live_bot.py:2921):
#   _zw (зона) · МАЛЪК_РАЗМЕР_W (пресност) · _рw (режим) · _пw (превес)
# а картата назоваваше само ПЪРВИТЕ ДВА. Измерено върху всичките 24
# комбинации: 18 (75%) режат размера по причина, за която картата НЕ КАЗВА
# НИЩО; най-лошата дава 4.1% от пълния размер и обяснява 16.5% от рязането.
# Живият сигнал от 01.09 09:32 излезе с 21% = 0.50 × 0.85 × 0.50 и картата
# обясняваше ЕДИН от три множителя.
# 🔴 И ЗАЩО ТОЗИ ТЕСТ Е НУЖЕН: когато сложих поправката, ВСИЧКИТЕ 2304
# теста минаха зелени. Тоест нищо не пазеше този ред — грешка в него би
# минала невидяна. Тестът, който не съществува, е зелен по устройство.
def _р117(режим, превес):
    _т117, _ок117 = lb._advice_entry("long", 1, stats, None, False, 0)
    _м117 = lb._sig_msg("long", 6, 5, "СИЛЕН", {"mid": 4365.2}, 4365.0, "x",
                        lb._levels(4365.2, "long"), 4365.2, _т117,
                        {"долар": True, "лихви": True}, 1, режим,
                        stats, 5000, 2.0, adv_ok=_ок117, превес=превес)
    return _re39.sub(r"<[^>]+>", "", _м117)

# ПОД 200-дневната (×0.50) И тесен превес (×0.50) — двата НЕМИ множителя
# 🔴 02.09 · `РЕЖИМ_W_ПОД` е вече 1.0 (отпушено). Режимът НЕ реже → и не се
# назовава като повод. Тестът се пуска с ИЗРИЧНО върнат множител, за да пази
# логиката; отдолу пази и новото поведение.
