# 🔴 И ОБРАТНАТА ПОСОКА — иначе тестът минава и при «винаги ги пиши»
_нереже117 = _р117({"vol_rank": .35, "below_sma200": False, "low_vol": True}, 9)
ck("П117 при силен режим думата я НЯМА", "режимът е слаб" not in _нереже117)
ck("П117 при широк превес думата я НЯМА", "превесът е тесен" not in _нереже117)
# и двата реда наистина се различават — иначе горните две могат да са едно
_ред117б = [x for x in _нереже117.split(chr(10)) if "размер:" in x]
