# ═══ П104 · ПРИБРАНО срещу ВИСЯЩО · картата не бива да ги смесва ════════
# 🔴 26.08 · `_ladder_pnl` смята ПОСЛЕДНАТА трета по ТЕКУЩАТА цена, все едно е
# излязла — а тя още стои. При ТП2 това дава +105 пипса, докато ПРИБРАНОТО е
# +65 пипса. СЛУЧИ СЕ ЖИВО на 25.08:
#     05:08 вход 4636.19 · 05:22 ТП1 · 05:32 ТП2 → картата обеща +105 пипса
#     07:11 остатъкът излезе на входа → реалното беше +65 пипса
# «Носи» звучи като прибрано, а не беше. Сега двете се казват ПООТДЕЛНО.
_E104 = 4650.0
_L104 = lb._levels(_E104, "long")
# ръчната сметка, за да няма кръгова проверка:
#   ТП1 прибрано (7.50)/3 = 2.50$ = 25 пипса · висят 2/3 × 7.50 = 5.00$
#   ТП2 прибрано 2.50 + 4.00 = 6.50$ = 65 пипса · виси 1/3 × 12.00 = 4.00$
#   ТП3 прибрано 2.50 + 4.00 + 6.667 = 13.17$ = 132 пипса · нищо не виси
for _вид, _hit, _цена, _очП, _очВ in (
        ("tp1", {"tp1": True}, _L104["tp1"], 2.50, 5.00),
        ("tp2", {"tp1": True, "tp2": True}, _L104["tp2"], 6.50, 4.00),
        ("tp3", {"tp1": True, "tp2": True, "tp3": True}, _L104["tp3"], 13.17, 0.0)):
    _п, _в, _n = lb._прибрано(_вид, _hit, _L104, _E104, 1, _цена - _E104, None)
    ck("П104 %s · ПРИБРАНО %.2f$ = %d пипса" % (_вид, _очП, round(_очП / lb.PIP)),
       abs(_п - _очП) < 0.02)
    ck("П104 %s · висящото е %.2f$" % (_вид, _очВ), abs(_в - _очВ) < 0.02)
# 🔴 ЖЕЛЯЗНО: прибрано + висящо = общото по стълбата (нищо не се губи, нищо
# не се брои два пъти)
for _вид, _hit, _цена in (("tp1", {"tp1": True}, _L104["tp1"]),
                          ("tp2", {"tp1": True, "tp2": True}, _L104["tp2"])):
    _дол = _цена - _E104
    _п, _в, _ = lb._прибрано(_вид, _hit, _L104, _E104, 1, _дол, None)
    _общо, _ = lb._ladder_pnl(_вид, _hit, _L104, _E104, 1, _дол, None)
    ck("П104 %s · прибрано + висящо = общото (%.2f + %.2f = %.2f)"
       % (_вид, _п, _в, _общо), abs((_п + _в) - _общо) < 0.02)
# 🔴 КАРТАТА го КАЗВА, и то с ПИПСОВЕ отпред
_тр104 = {"direction": "long", "entry": _E104, "levels": _L104,
          "hit": {"tp1": True, "tp2": True}, "sym": "XAUUSD", "v2": True, "ledger": "spot"}
_к104 = lb._exit_msg("tp2", _тр104, _L104["tp2"], "2026-08-26T10:00", "спот", False)
ck("П104 ТП2 картата казва ПРИБРАНО", "ПРИБРАНО" in _к104)

