# ═══ П103 · ЕДИНИЦАТА И ПИПСОВЕТЕ · математиката, която собственикът чете ═
# 🔴 26.08 · Собственикът: «купувам на 4650, 4655 вече са 50 пипса печалба».
# ПРАВ Е и ботът го смята вярно. Но картата казваше «200 пипса (20.00$)» без
# ЕДИНИЦА — а това са долари НА УНЦИЯ. При един стандартен лот (100 унции)
# същият стоп е 2000 ДОЛАРА. Сто пъти разлика в четенето на едно число.
#     1 унция (0.01 лот)    1 пипс = 0.10$   стоп 200п = −20$
#     10 унции (0.10 лот)   1 пипс = 1.00$   стоп 200п = −200$
#     100 унции (1 лот)     1 пипс = 10.00$  стоп 200п = −2000$
ck("П103 твоят пример: 4650 → 4655 са ТОЧНО 50 пипса",
   abs((4655.0 - 4650.0) / lb.PIP - 50) < 1e-9)
ck("П103 и ботът го изписва така", lb._разст(4650.0, 4655.0, "XAUUSD", 2)
   .startswith("50 пипса"))
ck("П103 ЕДИНИЦАТА е в текста, не се подразбира",
   "$/oz)" in lb._разст(4650.0, 4630.0, "XAUUSD", 2))
# 🔴 ЦЯЛАТА СТЪЛБА в пипсове — числата в TPS трябва да СЪВПАДАТ с долара
for _им103, _п103, _д103 in lb.TPS:
    ck("П103 %s: %.2f$ = %d пипса (както пише в TPS)" % (_им103, _д103, _п103),
       abs(_д103 / lb.PIP - _п103) < 1e-9)
ck("П103 стопът също: %.2f$ = %d пипса" % (lb.SL_D, round(lb.SL_D / lb.PIP)),
   abs(lb.SL_D / lb.PIP - 200) < 1e-9)
# 🔴 И НИВАТА от даден вход — аритметика, не греп
_л103 = lb._levels(4650.0, "long")
for _к103, _оч103 in (("tp1", 7.5), ("tp2", 12.0), ("tp3", 20.0)):
    ck("П103 от 4650 → %s е +%.2f$ = %d пипса" % (_к103, _оч103, round(_оч103 / lb.PIP)),
       abs((_л103[_к103] - 4650.0) - _оч103) < 0.011)
# 🔴 02.09 · ОБЪРНАТ. Стопът на ЛОНГА стана 130 пипса (`ЛОНГ_СТОП_ПИПСА`).
# Мерено с НЕПОКЪТНАТИ цели: 130п +0.669 [+0.016,+1.342] ✅ срещу 200п
# +0.810 [−0.034,+1.664] ⚪ — старото е НЕДОКАЗАНО, новото е доказано, и
# тегли с една трета по-малко (−1672$ срещу −2701$).
ck("П103 стопът следва ЛОНГ_СТОП_ПИПСА (%g пипса)" % lb.ЛОНГ_СТОП_ПИПСА,
   abs((4650.0 - _л103["sl"]) - lb.ЛОНГ_СТОП_ПИПСА * lb.PIP) < 0.011)
ck("П103 и ЦЕЛИТЕ са непокътнати (те не се пипат)",
   all(abs((_л103[k] - 4650.0) - v) < 0.011
       for k, v in (("tp1", 7.5), ("tp2", 12.0), ("tp3", 20.0))))
# 🔴 ОБРАТНАТА ПОСОКА: шортът е огледален, същите пипсове
_с103 = lb._levels(4650.0, "short")
# 🔴🔴 02.09 · ОБЪРНАТ, същата причина като П104. Двете посоки вече имат
# РАЗЛИЧНИ геометрии — това е промяната, не дефект.
_шг103 = lb.ШОРТ_ГЕОМЕТРИЯ
try:
    lb.ШОРТ_ГЕОМЕТРИЯ = False
    _лс103 = lb.ЛОНГ_СТОП_ПИПСА
    lb.ЛОНГ_СТОП_ПИПСА = 200.0
    _с103о = lb._levels(4650.0, "short")
    lb.ЛОНГ_СТОП_ПИПСА = _лс103
    ck("П103 при ИЗКЛЮЧЕНИ ДВАТА ключа шортът е огледален (7.5 / 20)",
       abs((4650.0 - _с103о["tp1"]) - 7.5) < 0.011
       and abs((_с103о["sl"] - 4650.0) - 20.0) < 0.011)
finally:
    lb.ШОРТ_ГЕОМЕТРИЯ = _шг103
_т103, _сл103, _ = lb._геом("short")
ck("П103 при ВКЛЮЧЕН флаг шортът носи СВОИТЕ разстояния",
   abs((4650.0 - _с103["tp1"]) - _т103[0]) < 0.011
   and abs((_с103["sl"] - 4650.0) - _сл103) < 0.011)
ck("П103 и посоката е ПАК обратна (цели под входа, стоп над него)",
   _с103["tp1"] < 4650.0 < _с103["sl"])
# 🔴 02.09 · ОБЪРНАТ. Двете посоки вече имат ЕДИН И СЪЩ стоп (130 пипса) —
# собственикът: «няма значение лонг или шорт». Ключът вече не е «шортът е
# по-къс от лонга», а «И ДВАТА са по-къси от най-далечната цел».
ck("П103 ДВАТА стопа са по 130 пипса (едно число за двете посоки)",
   abs((_с103["sl"] - 4650.0) - (4650.0 - _л103["sl"])) < 0.011)
ck("П103 и двата са ПО-КЪСИ от най-далечната цел — ТОВА е промяната",
   (_с103["sl"] - 4650.0) < (4650.0 - _с103["tp3"])
   and (4650.0 - _л103["sl"]) < (_л103["tp3"] - 4650.0))
# 🔴 СРЕБРОТО е на ДРУГА скала — пипсът му е 0.001$
ck("П103 среброто брои по СВОЯ пипс (0.001$), не по златния",
   lb._разст(58.970, 58.430, "XAGUSD", 3).startswith("540 пипса"))

# ═══ П40 · МОЗЪЧНИТЕ СИЛНИ СЕТЪПИ СА ВХОДОВЕ, НЕ НАБЛЮДЕНИЯ (ОДИТ-39) ═════
# Собственикът, 15-ия час: «искам сигнали, съвети, всичко от А до Я».
# Мозъкът виждаше сетъпи с вход, стоп и две цели — но ги наричаше
# «наблюдение» и НЕ даваше лот. Значи не бяха сигнали.
# СЕГА: под «✅ ГОТОВ» остават наблюдения; от «ГОТОВ» нагоре са ВХОДОВЕ с лот.
if _CB22 is not None:
    _осн40 = {"лонг": True, "цена": 4443.5, "atr": 6.1, "рамка": "15м",
              "време": _dt.datetime(2026, 8, 11, 14, 0, tzinfo=_dt.timezone.utc),
              "повод_текст": ["СИЛНА зона"], "всички_условия": {"D1_в_зона": True},
              "залог": {"вход": 4443.50, "стоп": 4437.44, "риск": 6.06,
                        "цел": 4453.00, "награда": 9.5, "основа_цел": "ликвидност",
                        "съотношение": 1.57, "цел2": 4462.50, "награда2": 19.0,
                        "основа_цел2": "гап", "съотношение2": 3.1}}
    _а40 = dict(таблица=_CB22.ТАБЛИЦА, тавани=_CB22.ТАВАН_ГРУПА,
                граници=_CB22.ПРАГОВЕ, степени=_CB22.СТЕПЕНИ)
    _ЛОТ40 = "💰 0.07 лот · риск ≈$42 · по 1/3 на цел"
    def _к40(ранг, степен, лот=None):
        return _CB22.KT.сглоби(dict(_осн40, ранг=ранг, степен=степен, точки=9 + ранг),
                               **_а40, час_сега="19:55", лот=лот)
    # 🔴 02.09 · степените идват от ЖИВАТА стълбица, не преписани на ръка —
    # смяна на знак в b_сливане.py вече не оставя тест, който тества фантом.
    _набл40 = _к40(1, _CB22.СТЕПЕНИ[1])
    _вх40 = _к40(3, _CB22.СТЕПЕНИ[3], _ЛОТ40)
    _силен40 = _к40(6, _CB22.СТЕПЕНИ[6], _ЛОТ40)
    _зн40 = lambda i: _CB22.СТЕПЕНИ[i].split(" ")[0]
    ck("П40 НАБЛЮДЕНИЕ си остава наблюдение (без лот, без КУПИ)",
       "наблюдение, не е вход" in _набл40 and "лот" not in _набл40
       and "КУПИ" not in _набл40 and _набл40.startswith(_зн40(1)))
    # 🔴🔴 02.09 · СТЪЛБИЦАТА ТРЯБВА ДА СЕ ВИЖДА. Дотук ранг 1..6 даваха
    # БАЙТ-ЕДНАКВО заглавие освен една дума: 💎 РЯДЪК изглеждаше като
    # 🔎 НАБЛЮДЕНИЕ. Седемте знака се строяха в b_сливане.py и се хвърляха
    # в b_карта.py с `.split(" ", 1)[-1]`.
    ck("П40 трите степени НЕ изглеждат еднакво (знакът ги различава)",
       len({_набл40[0], _вх40[0], _силен40[0]}) == 3)
    ck("П40 и знакът е ТОЧНО този на степента",
       _вх40.startswith(_зн40(3)) and _силен40.startswith(_зн40(6)))
    # 🔴 ОДИТ-43 · ОБЪРНАТ. Вчера този тест пазеше «🟢 КУПИ ЗЛАТО».
    # Собственикът, 20-ия час: «последните съобщения са все сякаш са вход
    # истински… трябва съвет за гледане накъде — сигналите са други».
    # Мозъкът НЯМА бектест; 🟢/🔴 КУПИ/ПРОДАЙ остават само за мереното правило.
    ck("П40 силният сетъп е СЪВЕТ «ГЛЕДАЙ», не заповед «КУПИ»",
       "ГЛЕДАЙ" in _вх40.split(chr(10))[0]
       and "КУПИ" not in _вх40 and "ПРОДАЙ" not in _вх40)
