_шип48.iloc[-1, 0] = float(_шип48.iloc[-2, 0]) + 200
_из48б, _кр48б = lb._изблик(_шип48)
ck(f"П48 сбъркан бар ПАЛИ тревога ({_кр48б:.0f}x)", _из48б)
