# 🔄 21.08 · ТОВА ТВЪРДЕНИЕ Е ОБЪРНАТО, НЕ ИЗТРИТО.
# Когато беше писано, прекъсвачът се отключваше САМО ако новата стойност е ПОД
# тавана — и затова «абсурдните 639$ пак се отхвърлят» беше вярно. После се
# доказа с изпълнение, че точно това условие Е дефектът: при истинска стойност
