# 100$ при таван 92.99$ → 60 ръна, брояч 60, стойността не мръдва). Прекъсвачът
# стана БЕЗУСЛОВЕН. Новото ЖЕЛАНО поведение има две страни, и двете се проверяват:
ck(f"П73 12 ПОРЕДНИ съгласни на 639$ ВЕЧЕ минават — системата се схожда, "
   f"не заключва (стана {_бг73:.2f})", abs(_бг73 - 639.0) < 1.5)
