# ═══ П74 · ОТБРОЯВАНЕТО ДО ГОЛЯМА НОВИНА (21.08) ═══════════════════════
# ПОИСКАНО: предупреждение поне 15 ЧАСА по-рано, после на всеки 2 ЧАСА.
# МЕРЕНОТО ДОТУК (live/sent_log.jsonl, преди FOMC 19.08 18:00 UTC):
#   180ч · 156ч · 132ч · 🔴 ТРИ ДНИ ТИШИНА (уикенд) · 60ч · 36ч · 12ч
# Тоест: веднъж на ден, само делник, последната дума на 12 часа.
_евт74 = "2026-08-27T10:00:00Z"                      # = 13:00 София
_cq74 = {"events": [{"name": "ФРС FOMC Решение за лихвите — Джексън Хоул",
                     "dt": _евт74, "impact": "critical"}]}
_КР74 = pd.Timestamp("2026-08-27T10:00")

def _симулирай74(крачка_мин):
    """Върти часовника със ЗАДАДЕНА крачка и връща часовете преди събитието,
    на които картата НАИСТИНА би излязла (с истинската логика на паметта)."""
    meta, кога = {}, []
    t = _КР74 - pd.Timedelta(hours=20)
    while t < _КР74:
        d = lb._news_due(_cq74, t.isoformat()[:16], meta)
        if d:
            кога.append((_КР74 - t).total_seconds() / 3600.0)
            # 🔴 01.09 · СИМУЛАТОРЪТ БЕШЕ ЗАСТОЯЛ. Той пишеше състояние БЕЗ
            # «етап», тоест възпроизвеждаше СТАРИЯ викащ, а истинският main()
            # вече го пази. Затова тестът виждаше 8 карти, докато ботът праща
            # 2 — мереше собствения си остарял двойник, не бота.
            # (Че резервният път за старо състояние работи, се пази отделно:
            # «в рамките на 2 часа от последната НЕ повтаря» подава запис БЕЗ
            # етап и иска мълчание.)
            meta["новина"] = {"кой": d[3], "utc": t.isoformat()[:16],
                              "етап": (d[5] if len(d) > 5 else None)}
        t += pd.Timedelta(minutes=крачка_мин)
    return кога

_к5 = _симулирай74(5)                                # нормалната крачка
_к15 = _симулирай74(15)                              # НАЙ-ЛОШИЯТ мерен сън за 7 дни
ck(f"П74 ПЪРВАТА дума идва поне 15ч преди (при 5 мин: {_к5[0]:.2f}ч)", _к5[0] >= 15.0)
ck(f"П74 и при най-лошия мерен сън от 15 мин ({_к15[0]:.2f}ч)", _к15[0] >= 15.0)
# 🔴 01.09 · ОБЪРНАТИ. «Точно на 2 часа» БЕШЕ ДЕФЕКТЪТ, не гаранцията:
# 15 часа напред ÷ 2 = осем еднакви карти за едно събитие. Сега ритъмът е
# ПО ЕТАПИ. Гаранцията, която ОСТАВА и е истинската: последната карта идва
# БЛИЗО до събитието — иначе предупреждението е безполезно.
_раз5 = [round(_к5[i] - _к5[i + 1], 2) for i in range(len(_к5) - 1)]
ck(f"П74 вече НЕ е на всеки 2 часа ({sorted(set(_раз5))})", set(_раз5) != {2.0})
ck(f"П74 последната карта е близо до събитието ({_к5[-1]:.2f}ч)", _к5[-1] <= 1.5)
ck(f"П74 и при 15-минутна крачка пак е близо ({_к15[-1]:.2f}ч)", _к15[-1] <= 1.5)
ck("П74 двете крачки дават ЕДНАКЪВ брой карти (не зависи от съня)",
   len(_к5) == len(_к15))
# 🔴 01.09 · ОБЪРНАТ. «Повече от една» ОСТАВА, но «поне 6» беше замразило
# точно дефекта: 15 часа ÷ 2 = ОСЕМ еднакви карти за ЕДНО събитие.
# Сега са 2 и това е целта. Виж П108 за пълния отброй.
ck(f"П74 картите са повече от една, но НЕ са осем ({len(_к5)})",
   2 <= len(_к5) <= 3)
# 🔴 ОБРАТНАТА ПОСОКА — да не стане спам
ck("П74 далечно събитие МЪЛЧИ (143ч преди)", lb._news_due(_cq74, "2026-08-21T10:00", {}) is None)
ck("П74 без календар МЪЛЧИ (защитено)", lb._news_due(None, "2026-08-27T09:00", {}) is None)
ck("П74 празен списък събития МЪЛЧИ", lb._news_due({"events": []}, "2026-08-27T09:00", {}) is None)
ck("П74 повреден момент не чупи бота",
   lb._news_due({"events": [{"name": "х", "dt": "БОКЛУК"}]}, "2026-08-27T09:00", {}) is None)
ck("П74 в рамките на 2 часа от последната НЕ повтаря",
   lb._news_due(_cq74, "2026-08-27T05:00",
                {"новина": {"кой": "ФРС FOMC Решение за лихвите — Джексън Хоул|" + _евт74,
                            "utc": "2026-08-27T04:00"}}) is None)
ck("П74 подмината дата НЕ вдига карта",
   lb._news_due(_cq74, "2026-08-27T11:00", {}) is None)
# 🔴 УИКЕНДЪТ. Мерено: събота 15.08 = 0 ръна, неделя 16.08 = 27 ръна.
# Понеделнишко събитие иска първа дума в НЕДЕЛЯ вечер.
_пн74 = {"events": [{"name": "NFP — Доклад за заетостта", "dt": "2026-08-31T12:30:00Z", "impact": "high"}]}
ck("П74 неделя вечер вдига карта за понеделнишко събитие (уикендът НЕ е сляп)",
   lb._news_due(_пн74, "2026-08-30T21:30", {}) is not None)
# самата карта
_д74 = lb._news_due(_cq74, "2026-08-26T18:30", {})
_т74 = lb._news_msg(_д74[0], _д74[1], _д74[2], _д74[3], _д74[4])
ck("П74 картата казва КОЛКО остава", "СЛЕД" in _т74)
ck("П74 картата казва ЧАСА по СОФИЙСКО", "13:00 София" in _т74)
ck("П74 картата казва КАКВО ПРАВИ БОТЪТ (спира нови входове)",
   "не отварям нов вход" in _т74)
ck("П74 картата УСПОКОЯВА за отворена сделка", "отворена сделка не се пипа" in _т74)
# 🔴 01.09 · ОБЪРНАТ. ДУХЪТ остава: картата казва какво следва. Но вече не
# обещава «пак след 2 часа» осем пъти — казва КОЛКО ОЩЕ ще има.
ck("П74 картата казва какво следва",
   ("ще ти се обадя още" in _т74) or ("остават още" in _т74)
   or ("последното напомняне" in _т74))
_п74 = lb._news_msg(_д74[0], _д74[1], 1.0, _д74[3], "повторение")
ck("П74 ПОСЛЕДНАТА карта НЕ обещава следваща (числото и думата не си противоречат)",
   "ще ти напомня пак" not in _п74 and "последното напомняне" in _п74)
ck("П74 първият ред се побира в тавана на стила (78)",
   max(len(x) for x in _т74.split(chr(10))[:1]) <= 78)
