# ═══ П76 · ПРЕКЪСВАЧЪТ НЕ БИВА ДА НАСЛЕДЯВА СЛЯПОТО СИ ПЕТНО (21.08) ════
# 🔴 ДЕФЕКТ В САМАТА ПОПРАВКА ОТ СЪЩИЯ ДЕН. Първата версия гласеше:
#     if state[_бр_к] >= BASIS_STUCK_N and abs(now_b) <= cap:
#                                         ^^^^^^^^^^^^^^^^^^ ТОЧНО грешното условие
# тоест освобождаването се съдеше от СЪЩИЯ таван, който трябваше да оспорва.
# ИЗПЪЛНЕНО тогава (таван 92.99$ при цена 4649$):
#     истински базис  58.8$ (ПОД тавана) → 60 ръна → 58.800, брояч  0  освободи се
#     истински базис 100.0$ (НАД тавана) → 60 ръна → 25.515, брояч 60  ЗАКЛЮЧЕН
# И аварията от 19.08, изиграна с онзи код при стария таван 40$: 100 ръна, пак
# заключен. Тоест поправката работеше само там, където дефектът не хапеше.
_БАР76 = 4649.3
_CAP76 = lb._basis_cap(_БАР76, "XAUUSD")


def _въртя76(истина, cap, ръна=60, старт=25.515, бар=_БАР76):
    """Върти N ръна с ПОСТОЯНЕН истински базис и връща (краен_базис, брояч, бележки)."""
    сп = {"bid": бар - истина - 0.25, "ask": бар - истина + 0.25, "mid": бар - истина, "src": "т"}
    ст = {"basis_g": старт, "basis_g_bar": бар - 2}
    н = []
    b = старт
    for _ in range(ръна):
        b = lb._basis_update(ст, "basis_g", сп, бар, н, cap=cap, now_utc="2026-08-21T10:30")
    return b, ст.get("basis_g_отказ", 0), н


for _ист76, _ет76 in ((58.8, "ПОД тавана"), (100.0, "НАД тавана"), (240.0, "далеч над тавана")):
    _b76, _бр76, _ = _въртя76(_ист76, _CAP76)
    ck(f"П76 базис {_ист76}$ ({_ет76}) СЕ ОСВОБОЖДАВА (стана {_b76:.2f})",
       abs(_b76 - _ист76) < 0.5)
# самата авария, изиграна със стария таван — трябва да се отпуши ВЪПРЕКИ него
_b76a, _, _н76a = _въртя76(47.74, 40.0, ръна=100, бар=4639.0)
ck(f"П76 аварията от 19.08 се отпушва ДОРИ при стария таван 40$ (стана {_b76a:.2f})",
   abs(_b76a - 47.74) < 0.5)
ck("П76 и го КАЗВА на глас", any("ЗАКЛЮЧЕН" in x for x in _н76a))
ck("П76 бележката носи БРОЯ наблюдения и разсейката",
   any("медиана на" in x and "разсейка" in x for x in _н76a))
# 🔴 ОБРАТНАТА ПОСОКА 1: ЕДИНИЧЕН глич не бива да презакотвя.
# Медианата съществува точно за това — един изрод не дърпа медиана.
_ст76г = {"basis_g": 55.0, "basis_g_bar": _БАР76 - 2}
_н76г = []
_норм76 = {"bid": _БАР76 - 55.2, "ask": _БАР76 - 54.8, "mid": _БАР76 - 55.0, "src": "т"}
_глич76 = {"bid": _БАР76 - 640, "ask": _БАР76 - 639, "mid": _БАР76 - 639.5, "src": "т"}
for _i76 in range(40):
    _b76г = lb._basis_update(_ст76г, "basis_g", _глич76 if _i76 % 9 == 0 else _норм76,
                             _БАР76, _н76г, cap=_CAP76, now_utc="2026-08-21T10:30")
ck(f"П76 ЕДИНИЧЕН глич 639$ НЕ дърпа базиса (остана {_b76г:.2f})", abs(_b76г - 55.0) < 6)
# 🔴 ОБРАТНАТА ПОСОКА 2: ПОСТОЯННО несъгласие ТРЯБВА да се приеме.
# 12 съгласни наблюдения бият едно старо число — иначе пак заключване.
_ст76п = {"basis_g": 55.0, "basis_g_bar": _БАР76 - 2}
_н76п = []
for _ in range(20):
    _b76п = lb._basis_update(_ст76п, "basis_g", _глич76, _БАР76, _н76п,
                             cap=_CAP76, now_utc="2026-08-21T10:30")
ck(f"П76 но 20 ПОРЕДНИ съгласни СЕ приемат (системата се схожда, не заключва)",
   abs(_b76п - 639.5) < 1.0)
# броячът и паметта се чистят при приемане
_ст76ч = {"basis_g": 55.0, "basis_g_bar": _БАР76 - 2, "basis_g_отказ": 7,
          "basis_g_отказани": [1.0, 2.0, 3.0]}
lb._basis_update(_ст76ч, "basis_g", _норм76, _БАР76, [], cap=_CAP76, now_utc="2026-08-21T10:30")
ck("П76 приемането нулира брояча И паметта",
   _ст76ч.get("basis_g_отказ") == 0 and _ст76ч.get("basis_g_отказани") == [])
# 🔴 УБИТИЯТ ТАВАН НЕ БИВА ДА Е СТОЙНОСТТА ПО ПОДРАЗБИРАНЕ.
# Дотук `cap=40.0` стоеше в подписа — всяко извикване без `cap=` мълчаливо
# връщаше дефекта, спрял бота за два дни.
_ст76д = {"basis_g": 25.515, "basis_g_bar": _БАР76 - 2}
_н76д = []
_сп76д = {"bid": _БАР76 - 58.8, "ask": _БАР76 - 58.6, "mid": _БАР76 - 58.8, "src": "т"}
for _ in range(20):
    _b76д = lb._basis_update(_ст76д, "basis_g", _сп76д, _БАР76, _н76д, now_utc="2026-08-21T10:30")
ck(f"П76 извикване БЕЗ cap= вече ползва ПРАВИЛНИЯ таван (стана {_b76д:.2f})",
   abs(_b76д - 58.8) < 0.5)
ck("П76 и среброто си получава СВОЯ таван по ключа",
   abs(lb._basis_cap(69.5, "XAGUSD") - 3.0) < 1e-9)

# ── БЛИЗНАКЪТ · _tf_basis ────────────────────────────────────────────────
# 🔴 Същият фиксиран таван (120$ = 6.00% от 2000$, но 2.59% от 4639$), НО без
# нито брояч, нито прекъсвач, нито изход: минеше ли веднъж, връщаше стария до
# края на времето. Живо: −3.9$ (02.08) → −61.6$ (21.08), 15.8× за 19 дни;
# собствената докстринг мери −238$ при роловър. Влиза в _scores(price_adj)
# и МЕНИ посоката на дъската.
def _рамки76(разлика, n=30, цена=4639.0):
    _idx = pd.date_range("2026-07-01", periods=n, freq="D")
    _iidx = pd.date_range("2026-07-01", periods=n * 24, freq="h")
    return (pd.DataFrame({"Close": [цена] * (n * 24)}, index=_iidx),
            pd.DataFrame({"Close": [цена + разлика] * n}, index=_idx))


for _раз76, _ет76 in ((-60.0, "ПОД тавана"), (-200.0, "НАД тавана (роловър)")):
    _ст76т = {"tf_basis_g": -61.599}
    _н76т = []
    _in76, _da76 = _рамки76(_раз76)
    for _ in range(30):
        _v76 = lb._tf_basis(_ст76т, "tf_basis_g", _in76, _da76, _н76т, days=20)
    ck(f"П76 контрактният базис {_раз76}$ ({_ет76}) СЕ ОСВОБОЖДАВА (стана {_v76:.1f})",
       abs(_v76 - _раз76) < 5)
ck("П76 контрактният таван РАСТЕ с цената (4639$ → 139$)",
   abs(max(lb.TF_BASIS_CAP, lb.TF_BASIS_CAP_PCT * 4639) - 139.17) < 0.5)
ck("П76 и при старите цени е както преди (2000$ → 120$)",
   abs(max(lb.TF_BASIS_CAP, lb.TF_BASIS_CAP_PCT * 2000) - 120.0) < 1e-9)
_ст76н = {"tf_basis_g": -61.599}
_н76н = []
_in76, _da76 = _рамки76(-200.0)
lb._tf_basis(_ст76н, "tf_basis_g", _in76, _da76, _н76н, days=20)
ck("П76 отказът на контрактния базис вече ОСТАВЯ СЛЕДА с число",
   any("пореден отказ" in x for x in _н76н))
ck("П76 и вече изобщо БРОИ (дотук нямаше дори брояч)",
   _ст76н.get("tf_basis_g_отказ") == 1)

# ═══ П77 · ЧЕТИРИ НАХОДКИ НА ЛОВЦИТЕ (21.08) ═══════════════════════════
# ── A · РЕ-АНКЕРЪТ НЕ БИВА ДА ФАБРИКУВА ИЗХОД ───────────────────────────
# 🔴 Дефект, ВЪВЕДЕН от собствената ми поправка отпреди час. Нивата на сделката
# идват от ЖИВАТА цена при отваряне (спот-свят). Баровете се превеждат с
# ТЕКУЩИЯ базис. Презакотви ли се базисът с една стъпка, баровете се местят
# спрямо неподвижни нива. ИЗПЪЛНЕНО с 12 АБСОЛЮТНО ПЛОСКИ бара:
#   базис 25.515 → 55.735 · лонг стоп 4611.68 · събития [('sl', 4591.465)]
#   шорт: и ТРИТЕ цели наведнъж. Пазарът не мръдна нито цент.
_idx77 = pd.date_range("2026-08-21 10:00", periods=12, freq="5min")
_плоски77 = pd.DataFrame({"Open": [4647.2] * 12, "High": [4648.0] * 12,
                          "Low": [4646.4] * 12, "Close": [4647.2] * 12}, index=_idx77)


def _сделка77(d="long"):
    _lv = ({"sl": 4611.68, "tp1": 4626.68, "tp2": 4631.68, "tp3": 4636.68} if d == "long"
           else {"sl": 4621.68, "tp1": 4616.68, "tp2": 4611.68, "tp3": 4606.68})
    return {"direction": d, "entry": 4621.68, "opened": "2026-08-21T09:00",
            "checked": "2026-08-21T09:00", "levels": _lv, "hit": {},
            "status": "open", "v2": True, "ledger": "spot"}


_, _ev77a = lb.track_trade(_сделка77(), _плоски77, 25.515, 4591.465, "2026-08-21T11:00")
ck("П77 без скок на базиса плоският пазар НЕ дава събития", not _ev77a)
_, _ev77б = lb.track_trade(_сделка77(), _плоски77, 55.735, 4591.465, "2026-08-21T11:00")
ck("П77 СТАРОТО поведение наистина фабрикуваше изход (дефектът е реален)",
   any(k == "sl" for k, *_ in _ev77б))
_, _ev77в = lb.track_trade(_сделка77(), _плоски77, 55.735, 4591.465, "2026-08-21T11:00",
                           скок_базис=True)
ck("П77 при презакотвяне баровете НЕ се съдят — нула фалшиви събития", not _ev77в)
# 🔴 21.08 · ТОЗИ ТЕСТ БЕШЕ ИЗЛЪГАН И ОБЯВИ ЗА ОПРАВЕН ДЕФЕКТ, КОЙТО БЕШЕ
# САМО ОТЛОЖЕН С ПЕТ МИНУТИ. Първата версия на пазача пропускаше баровете
# този рън, но `trade["checked"]` НЕ мърдаше (при празен `processed` блокът,
# който го придвижва, не се стига), а знамето важи за ЕДИН рън. Значи на
# СЛЕДВАЩИЯ рън същите барове пак са `ts > checked` и се съдеха — вече с
# новия базис. Ловец-агент го изпълни и получи ДУМА ПО ДУМА числата, които
# този тест обявяваше за фабрикувани:
#   рън на скока   → събития [] · checked НЕ Е мръднал
#   СЛЕДВАЩИЯТ рън → [('sl', 4591.465, ..., 'бар', True)] · сделката ЗАТВОРЕНА
# ПОУКАТА: тест, който гледа само първия такт, не проверява пазач — проверява
# закъснението му. Оттук нататък всяка от двете посоки минава ДВА ръна.
for _д77 in ("long", "short"):
    _т77 = _сделка77(_д77)
    _т77, _e77a = lb.track_trade(_т77, _плоски77, 55.735, 4591.465,
                                 "2026-08-21T11:00", скок_базис=True)
    ck(f"П77 {_д77}: рънът на скока не съди барове", not _e77a)
    # 🔴 МОЯТ ТЕСТ СЕ ХВАНА В КАПАНА, КОЙТО ТАЗИ БАЗА ВЕЧЕ ДОКУМЕНТИРА (ОДИТ-5,
    # L1-01): сравнявах НИЗОВЕ с РАЗЛИЧЕН формат. `checked` става
    # «2026-08-21 10:55:00» (интервал), а еталонът беше «2026-08-21T09:00» (T).
    # ' '(0x20) < 'T'(0x54) → сравнението даваше False за ВЕРНА стойност.
    # Затова: по СТОЙНОСТ, не по низ — точно както прави `_ts_le` в бота.
    ck(f"П77 {_д77}: и `checked` СЕ ПРИДВИЖВА (иначе е само отлагане)",
       pd.Timestamp((_т77 or {}).get("checked")) > pd.Timestamp("2026-08-21T09:00"))
    _т77б, _e77b = lb.track_trade(_т77, _плоски77, 55.735, 4591.465, "2026-08-21T11:05")
    ck(f"П77 {_д77}: СЛЕДВАЩИЯТ рън СЪЩО не фабрикува изход", not _e77b)
    ck(f"П77 {_д77}: и сделката е ЖИВА след двата ръна", _т77б is not None)
