# ═══ П119 · НИКОЙ НОВ НЕАТОМАРЕН ЗАПИС ═══════════════════════════════════
# 🔴 01.09 · П77 отгоре проверява, че ПОМОЩНИКЪТ е атомарен. Той НЕ проверява
# КОЙ го ползва — а точно това е въпросът. Синтактичен разбор на живия файл
# намира ЧЕТИРИ `.write_text(`, от които ТРИ заобикалят помощника:
#     1560  вътре в `_запиши_атомарно` (пише .tmp, после os.replace) — ВЯРНО
#     4966  пощата            `outbox.jsonl`
#     5122  макро-резервът    `macro_backup.json`
#     6742  състоянието на мозъка `brain_state.json`
#
# 🔴 ЗАЩО НЕ СЕ ПОПРАВЯТ ВЕДНАГА, А СЕ ЗАКОВАВАТ: оборвач измери риска на
# пощата — прозорецът, в който файлът е 0 байта, е 326 микросекунди в рън от
# 58 секунди (n=9408), тоест ~1 път на 360 години; НУЛА следи в 9408 ръна;
# пощата изобщо е непразна в 0.553% от ръновете и е носила ИЗХОДНА карта
# точно ВЕДНЪЖ в 9590 комита. А поправката има СВОЯ цена: при срив остава
# сирак `.tmp`, който `git add -A live/` качва в хранилището завинаги.
# Тоест: механизмът е рядък, поправката не е безплатна — но ПАЗАЧЪТ трябва
# да съществува, за да не порасне списъкът мълчаливо.
#
# ТОЗИ ТЕСТ ЗАКОВАВА СПИСЪКА ПО ИМЕ. Появи ли се НОВ неатомарен запис —
# червено. Махне ли се някой от трите — тестът пак пада и трябва да се
# обнови нарочно. Това е същият шаблон като `_ДОЛЕН_БРОЙ`: не поправя
# миналото, но спира мълчаливото израстване.
# ПЪТ НАЗАД: махане на блока. Нищо в бота не зависи от него.
import ast as _ast119

_изв119 = _ast119.parse(open("live_bot.py", encoding="utf-8").read())
_редове119 = sorted(
    _в.lineno for _в in _ast119.walk(_изв119)
    if isinstance(_в, _ast119.Call) and isinstance(_в.func, _ast119.Attribute)
    and _в.func.attr == "write_text")

# кой ред е ВЪТРЕ в `_запиши_атомарно` — той е законният
_атом119 = [_ф for _ф in _ast119.walk(_изв119)
            if isinstance(_ф, _ast119.FunctionDef) and _ф.name == "_запиши_атомарно"]
ck("П119 помощникът `_запиши_атомарно` съществува", len(_атом119) == 1)
_вътре119 = set()
if _атом119:
    _вътре119 = {_в.lineno for _в in _ast119.walk(_атом119[0])
                 if isinstance(_в, _ast119.Call) and isinstance(_в.func, _ast119.Attribute)
                 and _в.func.attr == "write_text"}
_вън119 = [_р for _р in _редове119 if _р not in _вътре119]

ck("П119 помощникът САМ ползва write_text (иначе разборът е сгрешен)",
   len(_вътре119) == 1)
# 🔴 ЗАКОВАНИЯТ БРОЙ. Расте ли — червено.
_ИЗВЕСТНИ119 = 3
ck(f"П119 неатомарните записи са точно {_ИЗВЕСТНИ119} (сега {len(_вън119)}) — "
   f"нов такъв е ЧЕРВЕНО",
   len(_вън119) == _ИЗВЕСТНИ119)
# и че разборът НАИСТИНА гледа кода, а не празен списък
ck("П119 разборът е намерил write_text изобщо", len(_редове119) >= 2)
# 🔴 И ОБРАТНАТА ПОСОКА: пазачът трябва да МОЖЕ да падне
ck("П119 сравнението не е тавтология", not (_ИЗВЕСТНИ119 + 1 == _ИЗВЕСТНИ119))

# ═══ П120 · ДВЕТЕ ВРАТИ ЗА ВХОД КАЗВАТ ЕДНО И СЪЩО ══════════════════════
# 🔴 01.09 · `_advice_entry` и `_reentry_verdict` отговарят на един въпрос и
# се викат в ЕДИН рън. Изпълнени върху 108 комбинации: 8 разминавания (7.4%),
# ВСИЧКИТЕ в опасната посока — ре-влизането ПУСКА там, където съветът ОТКАЗВА.
# ОДИТ-49 «БЕЗ ЧИСЛА НЯМА ВХОД» (v18.6) беше сложен само в едната врата.
# Резултатът на `_reentry_verdict` е ГЕЙТ (`if ok_re and cool_ok:`), не надпис.
# Тестът проверява СЪГЛАСИЕТО, не текста — и в двете посоки.
_ст120 = lb.СТАТ_ЗАДЪЛЖИТЕЛНА
lb.СТАТ_ЗАДЪЛЖИТЕЛНА = True
try:
    # `None` НЕ е «лоша статистика» — то е «не е подадена» (пътят за старите
    # извикващи) и се проверява отделно два реда по-долу. Живите извиквания
    # подават речник, никога None. Първата версия на теста ги смесваше.
    for _лош120 in ({}, {"fresh": "боклук"}, {"друго": {}}):
        _a120 = lb._advice_entry("long", 1, _лош120, None, False, 0)[1]
        _r120 = lb._reentry_verdict("long", 5, False, 0, stats=_лош120)[0]
        ck(f"П120 при лоша статистика {str(_лош120)[:14]!r} двете врати ОТКАЗВАТ",
           _a120 is False and _r120 is False)
    # обратната посока: с ДОБРА статистика ре-влизането НЕ се блокира от този клон
    _r120д = lb._reentry_verdict("long", 5, False, 0, stats=stats)
    ck("П120 при ДОБРА статистика клонът ОДИТ-49 не се намесва",
       _r120д[0] is True or "историческите числа" not in _r120д[1])
    # старият извикващ (без stats) пази старото поведение — нищо не се чупи назад
    ck("П120 без `stats` старото поведение е непокътнато",
       lb._reentry_verdict("long", 5, False, 0)[0] is True)
finally:
    lb.СТАТ_ЗАДЪЛЖИТЕЛНА = _ст120
# и двете ЖИВИ извиквания подават stats (иначе поправката е мъртва)
_изв120 = _src.count("_reentry_verdict(")
_със120 = _src.count("stats=stats)") + _src.count("stats=stats,")
ck("П120 двете живи извиквания подават stats", _изв120 >= 3 and _със120 >= 2)

# ═══ П121 · ТАВАНЪТ НА СДЕЛКИТЕ · ПОВЕДЕНИЕ, НЕ ТЕКСТ ═══════════════════════
# 🔴 01.09 · МУТАЦИЯ НА ЕДРО: и двете врати на тавана (`_слот_свободен =
# (...) < ТАВАН_СДЕЛКИ` и `len(доп_сделки) + 1 < ТАВАН_СДЕЛКИ`) обърнати на
# `<=` → ЗЕЛЕНО, целият пакет. При точно пълна книга ботът обявява слота за
# свободен и отваря ШЕСТА сделка при таван 5. Двете страни са цели числа —
# «границата» е всекидневният случай, не рядко съвпадение. Единственото
# червено беше от низово търсене, което умира, върне ли се литералът в
# коментар. Този тест изчислява СЪЩИЯ израз с живата константа, но проверява
# ПОВЕДЕНИЕТО на границата — и в двете посоки.
_т121 = lb.ТАВАН_СДЕЛКИ
ck("П121 таванът е цяло число ≥1", isinstance(_т121, int) and _т121 >= 1)
# израз 1 (реална + допълнителни) точно НА тавана → НЯМА слот
_пълна121 = (1 + (_т121 - 1)) < _т121
ck("П121 врата 1: точно пълна книга → слот НЯМА", _пълна121 is False)
# една под тавана → ИМА слот
_една121 = (1 + (_т121 - 2)) < _т121 if _т121 >= 2 else (0 < _т121)
ck("П121 врата 1: една под тавана → слот ИМА", _една121 is True)
# израз 2 (само допълнителни + 1) точно на тавана → НЯМА
ck("П121 врата 2: точно пълна книга → слот НЯМА", ((_т121 - 1) + 1 < _т121) is False)
# 🔴 и това, което пазим НАИСТИНА: изразите в живия код са със СТРОГО `<`
_ж121 = open("live_bot.py", encoding="utf-8").read()
ck("П121 врата 1 в живия код е СТРОГО `<` (не `<=`)",
   "+ len(доп_сделки)) < ТАВАН_СДЕЛКИ" in _ж121
   and "+ len(доп_сделки)) <= ТАВАН_СДЕЛКИ" not in _ж121)
ck("П121 врата 2 в живия код е СТРОГО `<` (не `<=`)",
   "len(доп_сделки) + 1 < ТАВАН_СДЕЛКИ" in _ж121
   and "len(доп_сделки) + 1 <= ТАВАН_СДЕЛКИ" not in _ж121)

# ═══ П124 · СУХИ_МАКС ИМА ГОРНА ГРАНИЦА ══════════════════════════════════
# 🔴 01.09 · Мутация ×2 → ЗЕЛЕНО. Единственият пазач беше «> 0» — проверка за
# съществуване, не за стойност. Това е ВТОРИЯТ будилник за мълчание (ръна без
# жива цена); удвояването му отлага тревогата, която трябваше да се обади
# вечерта на 19.08 вместо два дни мълчание. Заковавам живата стойност с
# горна граница, за да може мутацията да гръмне.
