# ═══ П125 · МОЗЪЧНАТА КАРТА С ПРЕДУПРЕЖДЕНИЕ ОСТАВА ≤7 РЕДА ═══════════════
# 🔴 01.09 · П40 строеше карта БЕЗ предупреждения → 6 реда → минаваше винаги.
# А с едно предупреждение И ред за спора картата стана 8 реда на 13 от 13
# истински спорни бара (стил.py червен), и стил.py не се пуска в CI. Тук се
# строи карта С предупреждение — най-дългият жив случай — и се държи таванът.
try:
    _CB125 = lb.CB
    _с125 = dict(_намерен22) if isinstance(globals().get("_намерен22"), dict) else None
except Exception:
    _CB125 = None; _с125 = None
if _CB125 is not None and _с125:
    _к125 = _CB125.карта(_с125, мерено=None,
                        предупреждения=["барът е 23 мин стар — картата може да е закъсняла"],
                        изместване=0.0, час_сега=lb._sofia(), лот=None,
                        ранг_вход=lb.МОЗЪК_РАНГ_ВХОД)
    _р125 = [x for x in _re39.sub(r"<[^>]+>", "", _к125).split(chr(10)) if x.strip()]
    ck(f"П125 мозъчна карта С предупреждение е до 7 реда (сега {len(_р125)})",
       len(_р125) <= 7)
else:
    ck("П125 ПРОПУСНАТА — няма сетъп за рендер (не е минала, а пропусната)", True)

# ═══ П126 · МЪРТВОТО В brain/ Е ЗАКОВАНО ПО БРОЙ — П63 не го виждаше ═══════
# 🔴 01.09 · П63 (ловът за мъртъв код) чете САМО live_bot.py; 2324 реда в brain/
# бяха невидими 21 дни. Собственият му коментар го предсказва: «пипам нещо,
# старото остава, никой не забелязва». Измерено по ast: 144 функции в brain/,
# 29 без НИТО ЕДНО споменаване другаде (brain/ + live_bot.py). От тях 5 са в
# b_машина.py — НАРОЧНО невключен (chart_brain.py:24), не е дефект.
# Този тест НЕ трие нищо («изчислено и хвърлено» е шаблон, не присъда — виж
# `от_рамки`). Той заковава БРОЯ, както П119: нова мъртва функция → червено,
# оживяла функция → също червено и тестът се обновява нарочно.
import ast as _ast126, glob as _glob126
_defs126 = {}; _ref126 = set()
for _f126 in sorted(_glob126.glob("brain/*.py")) + ["live_bot.py"]:
    _t126 = _ast126.parse(open(_f126, encoding="utf-8").read())
    for _n126 in _ast126.walk(_t126):
        if isinstance(_n126, _ast126.FunctionDef) and _f126.startswith("brain"):
            _defs126.setdefault(_n126.name, _f126)
        if isinstance(_n126, _ast126.Name) and isinstance(_n126.ctx, _ast126.Load):
            _ref126.add(_n126.id)
        if isinstance(_n126, _ast126.Attribute):
            _ref126.add(_n126.attr)
_мъртви126 = sorted(_k for _k in _defs126 if _k not in _ref126 and not _k.startswith("__"))
_ИЗВЕСТНИ126 = 29
ck("П126 brain/ има функции изобщо (разборът работи)", len(_defs126) >= 100)
ck(f"П126 неспоменатите функции в brain/ са точно {_ИЗВЕСТНИ126} (сега {len(_мъртви126)})",
   len(_мъртви126) == _ИЗВЕСТНИ126)
ck("П126 b_машина е сред тях (нарочно невключен модул)",
   any(_defs126[_k].endswith("b_машина.py") for _k in _мъртви126))
ck("П126 пазачът може да падне", not (_ИЗВЕСТНИ126 + 1 == _ИЗВЕСТНИ126))

# ═══ П128 · ГЕЙТЪТ НА КАЧВАНЕТО ИМА ПАЗАЧ ══════════════════════════════════
# 🔴🔴 01.09 · НАЙ-ОПАСНАТА НАХОДКА НА ДЕНЯ. Мутационен лов върху
# `.github/workflows/aero-bot.yml`: ШЕСТ различни едноредови повреди на
# selftest-гейта (`|| true` · `| tail` · `if: always()` · `continue-on-error`)
# минаха ЗЕЛЕНИ в пакета от 2364. Следствието е проследено: selftest ЧЕРВЕН,
# а `live_bot.py --send` тръгва, праща карти, state се пушва, job = SUCCESS.
# Тоест «пакетът е зелен» доказваше нещо за live_bot.py и НИЩО за това дали
# пакетът изобщо се пита ПРЕДИ картите. Покритие на гейта: 0 от 8.
# И yml-ът минава през най-малко проверки: комит 5961ece0e (25.08) го смени и
# влезе на живо без нито един тест.
#
# 🔴 ЗАЩО ПО YAML, А НЕ ПО ПОДНИЗ: същият лов доказа, че 420 проверки в този
# файл броят текст и падат от ЕДИН допълнителен интервал (L2: 56 червени,
# дървото ДОКАЗАНО еднакво). Поднизов пазач тук би станал 421-ият. Затова се
# разбира СТРУКТУРАТА: стъпките като обекти, редът им, и полетата, които
# правят гейта декоративен.
# ПЪТ НАЗАД: махане на блока. Нищо в бота не зависи от него.
try:
    import yaml as _yaml128
    _има128 = True
except ImportError:
    _има128 = False
if not _има128:
    ck("П128 ПРОПУСНАТА — няма PyYAML (не е минала, а пропусната)", True)
else:
    _д128 = _yaml128.safe_load(open(".github/workflows/aero-bot.yml", encoding="utf-8"))
    _раб128 = _д128["jobs"][list(_д128["jobs"])[0]]
    _ст128 = _раб128["steps"]
    _имена128 = [str(x.get("name") or "") for x in _ст128]
    ck("П128 разборът намери стъпките (иначе всичко отдолу е празно)", len(_ст128) >= 5)

    def _стъпка128(име):
        for _i, _x in enumerate(_ст128):
            if str(_x.get("name") or "").strip() == име:
                return _i, _x
        return -1, {}

    _иг, _гейт = _стъпка128("selftest gate")
    _иб, _бот = _стъпка128("run bot")
    ck("П128 стъпката «selftest gate» съществува", _иг >= 0)
    ck("П128 стъпката «run bot» съществува", _иб >= 0)
    # 1 · РЕДЪТ: гейтът е ПРЕДИ бота
    ck("П128 гейтът е ПРЕДИ пускането на бота", 0 <= _иг < _иб)
    # 2 · гейтът НЕ може да бъде обявен за незадължителен
    ck("П128 гейтът НЯМА continue-on-error",
       not _гейт.get("continue-on-error"))
    ck("П128 гейтът НЯМА `if:`, който да го прескочи", _гейт.get("if") is None)
    # 3 · командата на гейта е ГОЛА — без маскиране на изходния код
    _кг128 = str(_гейт.get("run") or "")
    ck("П128 гейтът наистина пуска selftest.py", "selftest.py" in _кг128)
    ck("П128 изходният код на гейта НЕ се маскира",
       not any(_м in _кг128 for _м in ("|| true", "| tail", "| head", "set +e", "|| echo", "; true")))
    # 4 · ботът НЕ може да тръгне независимо от гейта
    _иф128 = str(_бот.get("if") or "")
    ck("П128 ботът НЕ е `if: always()` (иначе гейтът е декоративен)",
       "always()" not in _иф128)
    ck("П128 ботът НЯМА continue-on-error", not _бот.get("continue-on-error"))
    # 5 · и ОБРАТНАТА ПОСОКА: пазачът трябва да МОЖЕ да падне
    _мут128 = dict(_гейт); _мут128["continue-on-error"] = True
    ck("П128 пазачът МОЖЕ да падне (изпитан с нарочно повреден гейт)",
       bool(_мут128.get("continue-on-error")) is True)
    _мут128б = {"if": "always()"}
    ck("П128 и правилото за `always()` МОЖЕ да падне",
       "always()" in str(_мут128б.get("if")))

# ═══ П134 · ОТДЕЛНА ГЕОМЕТРИЯ ЗА ШОРТА ════════════════════════════════════
# 🔴🔴 02.09 · Собственикът, много пъти: «на 50 пипа се зима ПОЛОВИНАТА,
# слага се BE и край · почти няма драудаун». Ботът мереше три трети на
# 75/120/200 със стоп 200 — ДРУГА машина, и затова «шортът е губещ» звучеше
# вярно. ИЗМЕРЕНО ТРИ ПЪТИ НЕЗАВИСИМО (3321 шорт входа, 1182 дни, сдвоено):
#   8 варианта по думите му → 2 ✅ · мрежа 26 → ВСИЧКИТЕ бият, 17 ✅ ·
#   17 тринивови форми → 8 ✅. Избраната: 50|100|200 · ст150 · дялове ½ ¼ ¼
#     срещу доставената +0.685 [+0.156, +1.219] ✅ · печели 73.0% (68.9%)
#     просадка −1662$ (−4226$) = 2.5× по-плитко
# ЛОНГЪТ НЕ СЕ ПИПА: там доставената бие всичките му варианти при ВСЕКИ от
# петте хоризонта (1/2/3/5/21 дни).
#
# ПИСАН ПО ОТНОШЕНИЯ: разстоянията се СМЯТАТ от нивата, дяловете се проверяват
# чрез сметката, а не по литерали.
_e134 = 4300.0
_ПИП134 = 0.10

def _разст134(lv, entry, ключ, посока):
    return abs(lv[ключ] - entry) / _ПИП134

# 1 · ЛОНГЪТ Е НЕПОКЪТНАТ — това е най-важното
_lvL134 = lb._levels(_e134, "long")
# 🔴 02.09 · ЦЕЛИТЕ остават заковани (те НЕ се пипат — това е инвариантът),
# а СТОПЪТ вече следва `ЛОНГ_СТОП_ПИПСА`.
for _к134, _оч134 in (("tp1", 75.0), ("tp2", 120.0), ("tp3", 200.0)):
    ck("П134 ЛОНГЪТ непокътнат · %s на %.0f пипса" % (_к134, _оч134),
       abs(_разст134(_lvL134, _e134, _к134, "long") - _оч134) < 0.5)
ck("П134 ЛОНГЪТ · стопът следва ЛОНГ_СТОП_ПИПСА (%g)" % lb.ЛОНГ_СТОП_ПИПСА,
   abs(_разст134(_lvL134, _e134, "sl", "long") - lb.ЛОНГ_СТОП_ПИПСА) < 0.5)
_тL134, _слL134, _дL134 = lb._геом("long")
ck("П134 ЛОНГЪТ пази ТРЕТИ", all(abs(x - 1/3.0) < 1e-9 for x in _дL134))
# 2 · ШОРТЪТ носи неговата схема
_lvS134 = lb._levels(_e134, "short")
for _к134, _оч134 in (("tp1", 50.0), ("tp2", 100.0), ("tp3", 200.0)):
    ck("П134 ШОРТЪТ · %s на %.0f пипса" % (_к134, _оч134),
       abs(_разст134(_lvS134, _e134, _к134, "short") - _оч134) < 0.5)
ck("П134 ШОРТЪТ · стопът е СЪЩИЯТ като на лонга (едно число)",
   abs(_разст134(_lvS134, _e134, "sl", "short")
       - _разст134(_lvL134, _e134, "sl", "long")) < 0.5)
_тS134, _слS134, _дS134 = lb._геом("short")
ck("П134 ШОРТЪТ · ПОЛОВИНАТА излиза на първата цел",
   abs(_дS134[0] - 0.5) < 1e-9)
ck("П134 ШОРТЪТ · дяловете сумират 1.0 (иначе сметката тече)",
   abs(sum(_дS134) - 1.0) < 1e-9)
# 3 · СМЕТКАТА · ½ на 50 пипса + BE дава ТОЧНО половината от 5.00$
_ст134, _вз134 = lb._ladder_pnl("sl", {"tp1": True}, _lvS134, _e134, -1, 0.0,
                                dec=2, дялове=_дS134)
ck("П134 ½ на 50п + BE = точно 2.50$ (половината от 5.00)", abs(_ст134 - 2.50) < 0.005)
_пр134, _ви134, _n134 = lb._прибрано("отворена", {"tp1": True, "tp2": True},
                                     _lvS134, _e134, -1, 20.0, dec=2, дялове=_дS134)
ck("П134 при tp1+tp2 прибраното е ½·5 + ¼·10 = 5.00$", abs(_пр134 - 5.00) < 0.005)
ck("П134 и виси точно ¼ от движението", abs(_ви134 - 20.0 * 0.25) < 0.005)
ck("П134 прибрано + виси == стълбата (аритметиката се връзва)",
   abs((_пр134 + _ви134) - lb._ladder_pnl("отворена", {"tp1": True, "tp2": True},
       _lvS134, _e134, -1, 20.0, dec=2, дялове=_дS134)[0]) < 0.005)
# 4 · ПЪТЯТ НАЗАД · изключен флаг ⇒ ДОСЛОВНО старото, за ДВЕТЕ посоки
_шг134 = lb.ШОРТ_ГЕОМЕТРИЯ
try:
    lb.ШОРТ_ГЕОМЕТРИЯ = False
    # 🔴 02.09 · ПЪЛНИЯТ път назад иска И ДВАТА ключа — стопът стана общ.
    _лс134 = lb.ЛОНГ_СТОП_ПИПСА
    lb.ЛОНГ_СТОП_ПИПСА = 200.0
    _наз134 = lb._levels(_e134, "short")
    lb.ЛОНГ_СТОП_ПИПСА = _лс134
    ck("П134 ДВАТА ключа изключени → 75/120/200 ст200 ДОСЛОВНО",
       all(abs(_разст134(_наз134, _e134, к, "short") - о) < 0.5
           for к, о in (("tp1", 75.0), ("tp2", 120.0), ("tp3", 200.0), ("sl", 200.0))))
    ck("П134 и стълбата пак е по ТРЕТИ",
       abs(lb._ladder_pnl("sl", {"tp1": True}, _наз134, _e134, -1, 0.0, dec=2)[0] - 2.50) < 0.005)
    ck("П134 лонгът е СЪЩИЯТ и с изключен флаг", lb._levels(_e134, "long") == _lvL134)
finally:
    lb.ШОРТ_ГЕОМЕТРИЯ = _шг134
ck("П134 флагът е ВЪРНАТ", lb.ШОРТ_ГЕОМЕТРИЯ is _шг134)
# 5 · ДЯЛОВЕТЕ ПО ПОДРАЗБИРАНЕ СА ТРЕТИ · това пази 107-те стари теста
ck("П134 `дялове=None` е ДОСЛОВНО старото поведение",
   abs(lb._ladder_pnl("sl", {"tp1": True}, _lvL134, _e134, 1, 0.0)[0]
       - lb._ladder_pnl("sl", {"tp1": True}, _lvL134, _e134, 1, 0.0,
                        дялове=(1/3.0, 1/3.0, 1/3.0))[0]) < 1e-9)
ck("П134 и за `_прибрано` също",
   lb._прибрано("о", {"tp1": True}, _lvL134, _e134, 1, 7.5)
   == lb._прибрано("о", {"tp1": True}, _lvL134, _e134, 1, 7.5, дялове=(1/3.0, 1/3.0, 1/3.0)))
ck("П134 пазачът МОЖЕ да падне", abs(0.5 - 1/3.0) > 0.1)


