# ═══ П132 · ГЕЙТЪТ РАЗДЕЛЯ «ДОКАЗАНО ВРЕДНО» ОТ «НЕИЗМЕРИМО» ═══════════════
# 🔴🔴 02.09 · Един `or` сливаше двете: `net < 0 ИЛИ _noise(seg)` → ОТКАЗ.
#     long/mixed   [−1.015, +0.062]  ⚪ горният край е НАД нулата
#     short/mixed  [−1.874, −0.704]  🛑 ЦЕЛИЯТ интервал е ПОД нулата
# Първата реже 66% от лонговете и е НАЙ-ГОЛЯМАТА клетка (28706 сд., 1495 дни);
# втората е доказано губеща и отказът ѝ е заслужен.
# Флагът е ТЕСЕН НАРОЧНО и ИЗКЛЮЧЕН по подразбиране.
# Тестът пази ТРИТЕ неща, които могат да се счупят мълчаливо:
#   1 · подразбирането НЕ мени нито едно решение
#   2 · включен, отпушва САМО long/mixed
#   3 · доказано губещото остава блокирано ПРИ ВСЯКА стойност на флага
# 🔴 собствен внос: `_io22` НЕ съществува в този файл (има _io2/_io21/_io46/
# _io115/_io116) — предположих име и тестът гръмна с NameError. Същият капан
# като с голото `os` (всичките вносове тук са `import os as _os`).
import io as _io132, json as _js132
_S132 = _js132.load(_io132.open("backtest_stats.json", encoding="utf-8"))

def _съд132(пос, стрийк, ст=None):
    _t = {}
    _txt, _ok = lb._advice_entry(пос, стрийк, ст if ст is not None else _S132,
                                 None, False, 0, trace=_t)
    return _ok, (_t.get("мерено") or {}).get("кофа")

