# ═══ П131 · ЧИСЛОТО ДО ДВЕ ЦЕНИ СЕ ВРЪЗВА С ТЯХ ═══════════════════════════
# 🔴🔴 02.09 · Намерено при обиколка по 149-те НАИСТИНА изпратени карти.
# Сянката слагаше сметка ПО СТЪЛБАТА върху ГОЛА двойка цени:
#     «💵 4,303.77 → 4,323.77 · +132 пипса (+13.17$)»
# Двете ПОКАЗАНИ цени се различават с 20.00$, а числото до тях казва 13.17$.
# Не е сметачна грешка — 13.17 = ⅓·7.5 + ⅓·12 + ⅓·20 Е вярно. Грешката е, че
# ДВЕ РАЗЛИЧНИ НЕЩА стоят на един ред и се четат като едно.
# ПРЕБРОЕНО с изпълнение: реалната карта 30/30 се връзва, сянката tp2 0/4,
# tp3 0/3. Живи карти от класа: 8 (sh-exit tp2 ×4, tp3 ×3, sl ×1).
#
# 🔴 ПИСАН КАТО АРИТМЕТИЧНО ОТНОШЕНИЕ: числото до стрелката се СМЯТА от двете
# показани цени и се сравнява. Никакъв литерал — козметика не го чупи, а
# връщането на слепването го чупи веднага.
_pари131 = _re39.compile(r"([+−-])(\d[\d,]*\.\d\d)\$")

def _дол131(ред):
    """доларите, изписани на реда, със знака — както ги чете човек"""
    _м = _pари131.search(ред)
    if not _м:
        return None
    return float(_м.group(2).replace(",", "")) * (-1 if _м.group(1) in ("-", "−") else 1)

_e131 = 4303.77
_lv131 = lb._levels(_e131, "long")
_tr131 = {"direction": "long", "entry": _e131, "levels": _lv131, "sym": "XAUUSD"}
_случаи131 = [("tp1", {"tp1": True}), ("tp2", {"tp1": True, "tp2": True}),
              ("tp3", {"tp1": True, "tp2": True, "tp3": True})]
for _k131, _h131 in _случаи131:
    _px131 = _lv131[_k131]
    for _име131, _ф131 in (("реалната", lb._exit_msg), ("сянката", lb._shadow_exit_msg)):
        _с131 = _re39.sub(r"<[^>]+>", "",
                          _ф131(_k131, dict(_tr131, hit=_h131), _px131, None, "спот", False))
        _р131 = [l for l in _с131.split(chr(10)) if l.startswith("💵")][0]
        ck("П131 %s · %s: числото до стрелката == разликата на ПОКАЗАНИТЕ цени"
           % (_име131, _k131),
           abs((_дол131(_р131) or 0.0) - (_px131 - _e131)) < 0.011)
# ── стълбата НЕ изчезва — тя има СОБСТВЕН ред, когато се различава ──────
_с131т = _re39.sub(r"<[^>]+>", "", lb._shadow_exit_msg(
    "tp3", dict(_tr131, hit={"tp1": True, "tp2": True, "tp3": True}),
    _lv131["tp3"], None, "спот", False))
_ст131, _ = lb._ladder_pnl("tp3", {"tp1": True, "tp2": True, "tp3": True},
                           _lv131, _e131, 1, _lv131["tp3"] - _e131, None, dec=2)
_общ131 = [l for l in _с131т.split(chr(10)) if l.startswith("💰")]
ck("П131 сянката пази СТЪЛБАТА на собствен ред", len(_общ131) == 1)
ck("П131 и този ред носи ТОЧНО стълбата (%.2f)" % _ст131,
   _общ131 and abs((_дол131(_общ131[0]) or 0.0) - _ст131) < 0.011)
ck("П131 двете числа са РАЗЛИЧНИ (иначе поправката е празна)",
   abs(_ст131 - (_lv131["tp3"] - _e131)) > 1.0)
# ── и МЪЛЧИ, когато съвпадат: цел1 остава 3 реда ───────────────────────
_с131а = _re39.sub(r"<[^>]+>", "", lb._shadow_exit_msg(
    "tp1", dict(_tr131, hit={"tp1": True}), _lv131["tp1"], None, "спот", False))
ck("П131 при цел1 вторият ред МЪЛЧИ (числата съвпадат)",
   _с131а.count(chr(10)) + 1 == 3 and "💰" not in _с131а)
# ── живата карта от 03:02: движение НАДОЛУ, стълба НАГОРЕ ───────────────
_e131б = 4303.14
_с131б = _re39.sub(r"<[^>]+>", "", lb._shadow_exit_msg(
    "sl", {"direction": "long", "entry": _e131б, "levels": lb._levels(_e131б, "long"),
           "sym": "XAUUSD", "hit": {"tp1": True, "tp2": True}},
    4300.35, None, "спот", True))
_дв131 = _дол131([l for l in _с131б.split(chr(10)) if l.startswith("💵")][0])
_об131 = _дол131([l for l in _с131б.split(chr(10)) if l.startswith("💰")][0])
ck("П131 движението е ОТРИЦАТЕЛНО (цената падна) и == показаните цени",
   _дв131 is not None and abs(_дв131 - (4300.35 - _e131б)) < 0.011 and _дв131 < 0)
ck("П131 а стълбата е ПОЛОЖИТЕЛНА — двете си казват истината едновременно",
   _об131 is not None and _об131 > 0)
# ── пътят назад ────────────────────────────────────────────────────────
_сдр131 = lb.СЯНКА_ДВА_РЕДА
try:
    lb.СЯНКА_ДВА_РЕДА = False
    _наз131 = _re39.sub(r"<[^>]+>", "", lb._shadow_exit_msg(
        "tp3", dict(_tr131, hit={"tp1": True, "tp2": True, "tp3": True}),
        _lv131["tp3"], None, "спот", False))
    ck("П131 СЯНКА_ДВА_РЕДА=не връща слепения ред ДОСЛОВНО",
       _наз131.count(chr(10)) + 1 == 3
       and abs((_дол131([l for l in _наз131.split(chr(10)) if l.startswith("💵")][0]) or 0) - _ст131) < 0.011)
finally:
    lb.СЯНКА_ДВА_РЕДА = _сдр131
ck("П131 пазачът МОЖЕ да падне", abs(13.17 - 20.00) > 0.011)


# ═══ П130 · ЧИСЛОТО, ПО КОЕТО СЕ ОТКАЗВА, СТИГА ДО КАРТАТА ═════════════════
# 🔴🔴 02.09 · ДОКАЗАНО С ИЗПЪЛНЕНИЕ, не с четене: `_sig_msg` приемаше 29
# параметъра и ДЕСЕТ никога не се четяха. Картата излизаше БАЙТ ЗА БАЙТ
# същата с празни и с пълни `stats`/`мерено`/`extra_ctx`/`macro`/`agree_n`.
# Тоест числата на клетката се смятат (`trace["мерено"]`), записват се в
# дневника — и умират по пътя към човека. К1 «изчислено и хвърлено», на
# най-важното решение на бота.
# Мерено на 149-те НАИСТИНА изпратени карти: 23 от 50 карти с ред «размер»
# казват НУЛА, и НИТО ЕДНА не носи числото зад отказа.
# ПИСАН ПО ОТНОШЕНИЯ: числото на картата се сверява с числото на КЛЕТКАТА,
# не с литерал. Смени клетката → трябва да се смени и картата.
import ast as _ast130

_кл130 = {"кофа": "mixed", "win": 68.6, "net": -0.47, "n": 28706,
          "lo": -1.015, "hi": 0.062, "дни": 1495}
