# ═══ П127 · ДВАТА ЛОНГ-ФЛАГА · ИЗКЛЮЧЕНИ ПО ПОДРАЗБИРАНЕ ═══════════════════
# 🔴 01.09 · «Лонг само над SMA200» (+36% сбор, −42% просадка) и «без лонг в
# петък» са РЕШЕНИЕ на собственика. Кодът ги носи като флагове, изключени по
# подразбиране: качването не мени поведението. Тестът пази ТРИТЕ неща, които
# трябва да са верни: (1) изключени → нищо; (2) включени → режат ТОЧНО каквото
# твърдят и нищо друго; (3) шортът е непокътнат винаги.
_под127 = {"below_sma200": True, "low_vol": False}
_над127 = {"below_sma200": False, "low_vol": False}
_пт127 = "2026-08-28T14:00"        # петък, 17:00 София
_ср127 = "2026-08-26T14:00"        # сряда
