# −748$ при TED=5 и −786$ при TED=21). Петъчният е ВЪРНАТ на «не», защото
# обосновката му падна при вярната мярка: махнатият петък е −146$ при TED=5,
# но само −76$ при TED=21, и комбинацията става 24$ ПО-ЛОША от SMA сам.
# Тестът пази ТОЧНО това състояние — и в двете посоки.
# 🔴🔴 02.09 · ОБЪРНАТ, НЕ ИЗТРИТ. Заковаваше «SMA-филтърът е ВКЛЮЧЕН».
# Собственикът го изключи, след като беше премерен върху ЖИВИТЕ входове (не
