# 🔴 02.09 · ОБЪРНАТ. При ИЗКЛЮЧЕН флаг лонгът под 200-дневната МИНАВА —
# това е новото поведение и то е смисълът на промяната. Логиката се пази
# отдолу с изрично включен флаг, за да не умре мълчаливо.
