# без нито един ред код. Проверява се като кодът ЧЕТЕ променливата.
_ж127пн = open("live_bot.py", encoding="utf-8").read()
# 🔴 01.09 · ОБЩ, не закован за конкретно подразбиране. Дотук изискваше и
