# от средата», каквото и да е подразбирането. Това важи и в двете посоки.
import re as _re127            # `re` не е на модулно ниво тук — същият капан като с `os`
# 🔴 02.09 · приема И `_env(`, И голото `os.environ.get(`. `_env` е същият
