_рег127 = _re127.compile(
    r'(?:_env|os\.environ\.get)\("(ЛОНГ_САМО_НАД_SMA200|БЕЗ_ЛОНГ_ПЕТЪК)",\s*"(да|не)"\)\s*==\s*"да"')
