ck(f"П79 очакваната цена вече съвпада с живата (разлика {abs(_р79 - 4588.0):.2f}$)",
   abs(_р79 - 4588.0) <= lb._spot_tol(_БАР79))
# 🔴 ОБРАТНАТА ПОСОКА 1: докато е кратко, резервата НЕ пипа базиса
_ст79б = {"basis_g": 25.515, "basis_g_bar": _БАР79 - 2}
