# ── L · `except` ЗАОБИКАЛЯШЕ СОБСТВЕНИЯ СИ ПРЕКЪСВАЧ ───────────────────
# 🔴 Външният try/except покрива целите 27 реда на пресмятането. Смени ли се име
# на колона, форма на индекса или pandas — връща се ПАЗЕНАТА стойност, броячът
# не мърда, бележка няма. Същото за двата ранни изхода.
# ИЗПЪЛНЕНО, С КОНТРОЛА: клонът «над тавана» → 60 бележки + отключване;
# клонът `except` → 60 ръна, 0 бележки, брояч 0. Дефектът е в разликата.
class _Счупен79:
    def resample(self, *a, **k):
        raise KeyError("Close")

    def __len__(self):
        return 100


_ст79л = {"tf_basis_g": -48.55}
_н79л = []
for _ in range(60):
    _v79 = lb._tf_basis(_ст79л, "tf_basis_g", _Счупен79(), _Счупен79(), _н79л, days=20)
ck(f"П79 счупен вход вече НЕ замразява контрактния базис (стана {_v79})", _v79 == 0.0)
ck("П79 и всеки отказ оставя дума (беше 0 бележки за 60 ръна)", len(_н79л) >= 60)
ck("П79 бележката назовава ТИПА на счупването", any("KeyError" in x for x in _н79л))
ck("П79 нулата е обявена, не мълчалива",
   any("пускам го на 0.00" in x for x in _н79л))
# 🔴 ОБРАТНАТА ПОСОКА: ЗДРАВ вход работи точно както преди, БЕЗ шум
_idx79 = pd.date_range("2026-07-01", periods=30, freq="D")
_iidx79 = pd.date_range("2026-07-01", periods=30 * 24, freq="h")
_in79 = pd.DataFrame({"Close": [4639.0] * (30 * 24)}, index=_iidx79)
_da79 = pd.DataFrame({"Close": [4639.0 - 48.0] * 30}, index=_idx79)
_ст79з = {}
_н79з = []
_v79з = lb._tf_basis(_ст79з, "tf_basis_g", _in79, _da79, _н79з, days=20)
ck(f"П79 ЗДРАВ вход дава верния контрактен базис ({_v79з:.2f})", abs(_v79з + 48.0) < 0.5)
ck("П79 и мълчи, когато няма какво да каже", not _н79з)

# ── M · ОТМЕНЕН ТОКЕН УНИЩОЖАВАШЕ КАРТИТЕ ─────────────────────────────
# 🔴 401 (отменен токен) и 403 (ботът изгонен) падаха в кофата на развален HTML.
# След 3 ръна картата се хвърляше със статус «ОТРОВНО-ХВЪРЛЕНО (развален HTML)».
# Пазачът за липсващ токен не палеше — токен ИМА, просто невалиден. Изход 0,
# алармата не гърми, дневникът зелен.
# ИЗПЪЛНЕНО: рън 4 хвърли карта с изряден HTML `<b>ЛОНГ 4639</b> вход сега`.
_орг79 = lb._send_raw
try:
    lb._send_raw = lambda t: "AUTH_FAIL:401 Unauthorized"
    _д79 = _P(_tf.mkdtemp())
    _ст79м = []
    _гръмна = False
    try:
        lb._outbox_flush(_д79, [("signal", "<b>ЛОНГ 4639</b> вход сега")], _ст79м, dry=False)
    except SystemExit as _e79:
        _гръмна = True
        _изх79 = str(_e79)
    ck("П79 отменен токен ГРЪМВА рънa (алармата в workflow-а пали)", _гръмна)
    ck("П79 картата ОСТАВА в пощата, не се хвърля",
       len([x for x in (_д79 / "outbox.jsonl").read_text(encoding="utf-8").splitlines() if x.strip()]) == 1)
    ck("П79 текстът казва САМОЛИЧНОСТ, не «развален HTML»",
       any("САМОЛИЧНОСТТА" in x for x in _ст79м) and not any("развален HTML" in x for x in _ст79м))
    ck("П79 и носи точния код от Телеграм", "401" in _изх79)
    ck("П79 не твърди «липсва токен», когато токен ИМА", "няма TELEGRAM_TOKEN" not in _изх79)
    # 🔴 ОБРАТНАТА ПОСОКА 1: истински развален HTML ПАК се осъжда след 3 ръна
    lb._send_raw = lambda t: "HARD_FAIL:400 Bad Request: can't parse entities"
    _д79б = _P(_tf.mkdtemp())
    _ст79б = []
    for _i79 in range(lb.POISON_HARD_FAILS + 1):
        lb._outbox_flush(_д79б, [("status", "<b>развален")] if _i79 == 0 else [],
                         _ст79б, dry=False)
    ck("П79 истински развален HTML ПАК се хвърля (пазачът е жив)",
       any("ОТРОВНО-ХВЪРЛЕНО" in x for x in _ст79б))
    # 🔴 ОБРАТНАТА ПОСОКА 2: липсващ токен си остава със СВОЯ текст
    lb._send_raw = lambda t: "DRY_RUN"
    _д79в = _P(_tf.mkdtemp())
    _ст79в = []
    _изх79в = ""
    try:
        lb._outbox_flush(_д79в, [("signal", "х")], _ст79в, dry=False)
    except SystemExit as _e79в:
        _изх79в = str(_e79в)
    ck("П79 наистина липсващ токен си пази СВОЯ текст",
       "няма TELEGRAM_TOKEN" in _изх79в and "САМОЛИЧНОСТ" not in _изх79в)
finally:
    lb._send_raw = _орг79

