# ── P · ТРИ ПАЗАЧА ПАДАХА НАВЕДНЪЖ И МЪЛЧАХА ───────────────────────────
# 🔴 `_market_closed`, `_cme_pause` и `_in_shield` питат САМО 'America/New_York'
# и всеки завършва с `except: return False` = «безопасно е».
# ИЗПЪЛНЕНО: без тази зона СЪБОТА минава за отворен пазар, CME паузата изчезва
# (значи базисът ре-анкерва върху фалшив скок, а спотът пуска крипто-прокси
# срещу затворен фючърс), US-щитът изчезва. Нито print, нито бележка.
# Пазачът не се чупи — той тихо престава да съществува.
# 🔴 ОБРАТНАТА ПОСОКА ПЪРВО: пазачите съдят ВЯРНО при здрава система
ck("П80 СЪБОТА е затворен пазар", lb._market_closed("2026-08-22T12:00") is True)
ck("П80 ПЕТЪК по обед е отворен", lb._market_closed("2026-08-21T12:00") is False)
ck("П80 17:30 Ню Йорк Е CME пауза", lb._cme_pause("2026-08-21T21:30") is True)
ck("П80 12:00 UTC НЕ е пауза", lb._cme_pause("2026-08-21T12:00") is False)
ck("П80 при здрава система знамето мълчи", not lb.ЧАСОВИ_ЗОНИ_СЧУПЕНИ)
# а сега — липсва ли зоната, вече СЕ ОБАЖДА
import zoneinfo as _zi80
_орг80 = _zi80.ZoneInfo


class _БезNY80:
    def __new__(cls, име):
        if име == "America/New_York":
            raise _zi80.ZoneInfoNotFoundError(име)
        return _орг80(име)


try:
    _zi80.ZoneInfo = _БезNY80
    lb.ЧАСОВИ_ЗОНИ_СЧУПЕНИ = ""
    _съб80 = lb._market_closed("2026-08-22T12:00")
    ck("П80 без зоната пазачът наистина пада (дефектът е реален)", _съб80 is False)
    ck("П80 но вече ВИКА, вместо да мълчи", bool(lb.ЧАСОВИ_ЗОНИ_СЧУПЕНИ))
    ck("П80 знамето назовава КОЯ зона липсва", "America/New_York" in lb.ЧАСОВИ_ЗОНИ_СЧУПЕНИ)
    ck("П80 София продължава да работи (не пада всичко)", lb._sofia("2026-08-21T10:00") == "13:00")
finally:
    _zi80.ZoneInfo = _орг80
    lb.ЧАСОВИ_ЗОНИ_СЧУПЕНИ = ""
ck("П80 знамето стига до ДНЕВНИКА, не до stdout", "СА ИЗКЛЮЧЕНИ, без да са спирани" in _ИЗХОД)
ck("П80 ВСИЧКИ зони минават през един помощник",
   _ИЗХОД.count('ZoneInfo("America') == 0 and _ИЗХОД.count('_tz("America/New_York")') >= 3)

