# ═══ П82 · БРОЯЧЪТ НЕ БИВА ДА ИЗПРЕВАРВА ДОКАЗАТЕЛСТВАТА (21.08) ═══════
# 🔴 ТРЕТИ ДЕФЕКТ В СОБСТВЕНАТА МИ ПОПРАВКА ЗА ДЕНЯ. Докстрингът на
# `_прекъсвач` обещава дословно «един изрод не може да дърпа медиана». Но в
# `_tf_basis` ДВА изхода деляха ЕДИН брояч, а само единият пълнеше списъка с
# наблюдения: тихият клон вдигаше `_отказ`, без да остави нито едно.
# ИЗПЪЛНЕНО: 11 ръна през тихия клон → брояч 11, наблюдения НУЛА; после ЕДИН
# изроден образец над тавана → брояч 12 ≥ N → медиана на ЕДИН елемент = самият
# глич. Стойността се закотви на −900.00 при истина −61.6, а замърсяването
# отшумява бавно през EMA (грешка 199$ на 5-ия рън, 47$ на 10-ия).
# Собствената бележка на бота дословно го признаваше: «медиана на 1 наблюдения».
_ст82 = {"tf_basis_g": -61.599}
_н82 = []
for _ in range(11):
    lb._tf_basis(_ст82, "tf_basis_g", None, None, _н82, days=20)
ck("П82 тихият клон има СВОЙ брояч (различна беда, различен лек)",
   _ст82.get("tf_basis_g_тих") == 11)
ck("П82 и НЕ пълни чуждия брояч за медианата",
   not _ст82.get("tf_basis_g_отказ"))
_idx82 = pd.date_range("2026-07-01", periods=30, freq="D")
_iidx82 = pd.date_range("2026-07-01", periods=720, freq="h")
_in82 = pd.DataFrame({"Close": [4639.0] * 720}, index=_iidx82)
_v82 = lb._tf_basis(_ст82, "tf_basis_g",
                    _in82, pd.DataFrame({"Close": [4639.0 - 900.0] * 30}, index=_idx82),
                    _н82, days=20)
ck(f"П82 ЕДИН изроден образец НЕ закотвя (остана {_v82})", abs(_v82 + 61.599) < 1.0)
ck("П82 и НЕ се хвали с «медиана на 1»",
   not any("медиана на 1 наблюдения" in x for x in _н82))
# 🔴 ОБРАТНАТА ПОСОКА: N ПОРЕДНИ СЪГЛАСНИ пак минават — не заключва
_ст82б = {"tf_basis_g": -61.599}
_н82б = []
for _ in range(14):
    _v82б = lb._tf_basis(_ст82б, "tf_basis_g", _in82,
                         pd.DataFrame({"Close": [4639.0 - 200.0] * 30}, index=_idx82),
                         _н82б, days=20)
ck(f"П82 но 14 ПОРЕДНИ съгласни СЕ приемат (стана {_v82б})", abs(_v82б + 200.0) < 5.0)
ck("П82 медианата вече стъпва на N наблюдения, не на едно",
   any("медиана на 12 наблюдения" in x or "медиана на 13" in x or "медиана на 14" in x
       for x in _н82б))
# и самият пазач: броячът не може да изпревари списъка ПО НИКОЙ ПЪТ
_ст82в = {"basis_g": 55.0, "basis_g_bar": 4647.0, "basis_g_отказ": 99}
_н82в = []
lb._basis_update(_ст82в, "basis_g", {"bid": 4000.0, "ask": 4001.0, "mid": 4000.5, "src": "swq"},
                 4647.0, _н82в, cap=lb._basis_cap(4647.0), now_utc="2026-08-21T10:30")
ck("П82 подправен брояч се СВЕЖДА до броя наблюдения",
   int(_ст82в.get("basis_g_отказ", 0)) <= len(_ст82в.get("basis_g_отказани") or []))
ck("П82 и затова не презакотвя на едно наблюдение", abs(_ст82в["basis_g"] - 55.0) < 0.01)
# предупреждението до допуска
ck("П82 до SPOT_TOL_PCT стои измереното предупреждение",
   "НЕ Я ВДИГАЙ" in _ИЗХОД and "10.3%" in _ИЗХОД)

# ═══ П83 · КАЛЕНДАРЪТ, РЕЗЕРВЪТ И ДНЕВНИЯТ ЧАСОВНИК (21.08) ════════════
# ── W · КОЗМЕТИЧНО ЧИСЛО ДЪРЖЕШЕ КЛЮЧА НА ЦЕЛИЯ КАЛЕНДАР ───────────────
# 🔴 `_cq_fetch` беше ЕДИН try върху три различни неща. `score` се ползва САМО
# за реда «🌡 крипто настроение … само за фон» — картата сама заявява, че е
# декорация. Липсваше ли, ЦЕЛИЯТ календар изчезваше, тоест макро-щитът И
# отброяването до новина висяха на козметично число.
# ИЗПЪЛНЕНО с РЕАЛНИ отговори от мрежата, подправени по едно поле:
#   всичко наред                               → 5 събития
#   терминалът без 'score' (календарът е ЖИВ)  → None (ЦЕЛИЯТ КАЛЕНДАР ИЗЧЕЗВА)
#   score = null (календарът е ЖИВ)            → None (ЦЕЛИЯТ КАЛЕНДАР ИЗЧЕЗВА)
ck("П83 декорацията вече има СВОЙ try", "score, fg = None, {}" in _ИЗХОД)
ck("П83 и резултатът приема липсващ score", "if score is not None else None" in _ИЗХОД)
ck("П83 картата понася score=None",
   isinstance(lb._cq_msg({"events": [], "score": None, "zone": ""}, "2026-08-21T10:00"), str))
_к83 = lb._cq_msg({"events": [{"name": "FOMC", "dt": "2026-08-27T10:00:00Z"}],
                   "score": None, "zone": ""}, "2026-08-21T10:00")
ck("П83 и пак казва идващото събитие без декорацията", "FOMC" in _к83)

# ── X · ПРАЗЕН КАЛЕНДАР ПРЕЗАПИСВАШЕ ДОБРИЯ КЕШ ────────────────────────
# 🔴 Филтърът съди по ЧУЖДА подредба (`affectsAssets`). Преименува ли
# доставчикът полето, `events` става [], но dict-ът е валиден → кешът се
# ПРЕЗАПИСВА с 0 събития и денят се маркира като успех.
# ИЗПЪЛНЕНО: полето преименувано → dict? True · събития: 0 → ЗАПИСВА СЕ.
# Оттам картата казва «✅ няма голямо макро събитие пред нас» — мълчанието се
# преоблича в ПОЛОЖИТЕЛНО потвърждение, а отброяването не пали нито веднъж.
ck("П83 празен календар при НЕПРАЗНА суровина се хвърля", "if raw and not events:" in _ИЗХОД)
ck("П83 и главният цикъл пази стария", "пазя стария" in _ИЗХОД)
ck("П83 суровият брой се записва за проверимост", '"raw_n": len(raw)' in _ИЗХОД)
# 🔴 ОБРАТНАТА ПОСОКА: наистина празен ден (нула сурови) НЕ бива да гърми
ck("П83 наистина празен отговор не се смята за счупен",
   "if raw and not events:" in _ИЗХОД)   # `raw` празно → условието е False

# ── Y · МАКРО-РЕЗЕРВЪТ БЕШЕ МЪРТЪВ В НАЧАЛОТО НА ВСЯКА СЕДМИЦА ─────────
# 🔴 Таван 36 часа СТЕННО време срещу МЕРЕНА уикендна дупка 49.1ч (петък 20:55
# → неделя 22:02, живи данни). 49.27 > 36 → резервът се отхвърля БЕЗ ДА Е
# ОПИТАН, в първия рън на всяка нова търговска седмица.
ck("П83 резервът брои ТЪРГОВСКО време", "_търговски_минути(_рез[" in _ИЗХОД)
_уик83 = lb._търговски_минути("2026-08-14T20:55", "2026-08-16T22:02") / 60.0
ck(f"П83 уикендната дупка в ТЪРГОВСКИ часове е под тавана ({_уик83:.1f}ч < {lb.СТАР_МАКРО_Ч})",
   _уик83 <= lb.СТАР_МАКРО_Ч)
_стенно83 = (pd.Timestamp("2026-08-16T22:02") - pd.Timestamp("2026-08-14T20:55")).total_seconds() / 3600
ck(f"П83 а по СТЕННО време е {_стенно83:.1f}ч — над тавана (дефектът е реален)",
   _стенно83 > lb.СТАР_МАКРО_Ч)
# 🔴 ОБРАТНАТА ПОСОКА: НАИСТИНА стар резерв пак се отхвърля
_стар83 = lb._търговски_минути("2026-08-10T12:00", "2026-08-21T12:00") / 60.0
ck(f"П83 резерв отпреди 11 дни ПАК се отхвърля ({_стар83:.0f}ч)", _стар83 > lb.СТАР_МАКРО_Ч)

