# ═══ П84 · ФИЛТЪРЪТ, СЛЕДАТА НА СПОТА И ЗАКОВАНИТЕ ВЕРСИИ (21.08) ══════
# ── AA · ФИЛТЪРЪТ ИЗЯЖДАШЕ PCE ────────────────────────────────────────
# 🟡 Съдеше САМО по `affectsAssets` — ЧУЖДО поле с ЧУЖДА подредба. PCE е макро
# за златото, но доставчикът го маркира като крипто/акции → изпадаше от
# календара, тоест нито макро-щит, нито отброяване до новина.
def _филтър84(e):
    """Дословна реплика на решаващия ред в `_cq_fetch`."""
    _а = str(e.get("affectsAssets", "")).upper()
    _им = str(e.get("title", ""))
    _imp = str(e.get("impact", "")).lower()
    return _imp in ("high", "critical") and (
        any(x in _а for x in ("GOLD", "XAU", "DXY", "USD"))
        or any(k in _им.upper() for k in lb.МАКРО_ИМЕНА))


ck("П84 PCE минава ДОРИ маркирано като крипто (по ИМЕ)",
   _филтър84({"title": "PCE — Индекс на личните потребителски разходи",
              "impact": "high", "affectsAssets": "CRYPTO,STOCKS"}))
ck("П84 ФРС решение пак минава (по АКТИВ, старият път е жив)",
   _филтър84({"title": "ФРС — Решение за лихвен процент",
              "impact": "critical", "affectsAssets": "GOLD,USD"}))
ck("П84 NFP минава по име", _филтър84({"title": "NFP — Доклад за заетостта",
                                       "impact": "high", "affectsAssets": ""}))
# 🔴 ОБРАТНАТА ПОСОКА: чуждото НЕ бива да влиза
ck("П84 биткойн халвинг НЕ минава (не е макро за златото)",
   not _филтър84({"title": "Биткойн халвинг", "impact": "high", "affectsAssets": "CRYPTO"}))
ck("П84 и НИСКА важност НЕ минава, дори с макро име",
   not _филтър84({"title": "CPI — второстепенна ревизия", "impact": "low",
                  "affectsAssets": "GOLD"}))
ck("П84 списъкът покрива и кирилица (заглавията идват на български)",
   any("ЛИХВ" in k for k in lb.МАКРО_ИМЕНА) and any("ФРС" in k for k in lb.МАКРО_ИМЕНА))
ck("П84 има път назад (МАКРО_ИМЕНА е от средата)",
   'os.environ.get(' in _ИЗХОД and "МАКРО_ИМЕНА" in _ИЗХОД)

# ── BB · `_spot` ГЪЛТАШЕ УМРЯЛА МРЕЖА БЕЗМЪЛВНО ───────────────────────
# 🟡 Умре ли мрежата или смени ли Swissquote схемата си, функцията връщаше None
# ТОЧНО както при затворен пазар — двете състояния бяха неразличими.
# ЧЕСТНО ЗА ТЕЖЕСТТА: латентно, не текущо. От 4242 живи ръна има 76 случая
# spot=None без отрязване и ВСИЧКИТЕ 76 са в час 21 UTC (CME паузата), тоест
# по устройство. Реални попадения от мъртва мрежа: 0.
_орг84 = lb.urllib.request.urlopen
try:
    lb.urllib.request.urlopen = lambda *a, **k: (_ for _ in ()).throw(TimeoutError("мрежата умря"))
    _сл84 = []
    _r84 = lb._spot("XAU/USD", следа=_сл84)
    ck("П84 при мъртва мрежа спотът пак връща None (нищо не се чупи)", _r84 is None)
    ck(f"П84 но вече оставя СЛЕДА ({len(_сл84)} източника)", len(_сл84) >= 2)
    ck("П84 следата назовава ТИПА на провала", any("TimeoutError" in str(x) for x in _сл84))
    ck("П84 и КОЙ източник е паднал", any("swq" in str(x) for x in _сл84))
    ck("П84 резервната верига също оставя следа",
       any("paxg" in str(x[0]) for x in _сл84))
finally:
    lb.urllib.request.urlopen = _орг84
ck("П84 главният поток КАЗВА кой как е паднал",
   "живата цена НЕ СЕ ДЪРПА" in _ИЗХОД)
# 🔴 ОБРАТНАТА ПОСОКА: не вика при затворен пазар и в CME паузата
ck("П84 но НЕ вика при затворен пазар или CME пауза",
   "not weekend and not _cme_pause(now_utc)" in _ИЗХОД)

# ── Ц5 · ВЕРСИИТЕ СА ЗАКОВАНИ ─────────────────────────────────────────
# 🟡 Дотук pandas/numpy/pyyaml бяха с граница по ГЛАВНА версия — тоест едно ново
