# ═══ П85 · ОДИТ-РОБОТЪТ МЕРЕШЕ НИВА ОТПРЕДИ ТЕ ДА СЪЩЕСТВУВАТ (21.08) ═══
# 🔴 ДВА ДЕФЕКТА В САМИЯ ОДИТОР, и двата от един и същи вид: прозорецът за
# «кога е ударено» тръгваше от `opened` за ВСЯКО ниво.
#  1) BE-СТОПЪТ. След ТП1 стопът се мести на входа. `levels["sl"]` носи
#     ФИНАЛНОТО ниво → цената пресича входа ЧАСОВЕ преди ТП1 да е ударен и това
#     се брои за «стоп». ДОКАЗАНО върху живата сделка от 28.07: отворена 02:10,
#     ТП1 пратен 05:35, стоп 06:01 — а одиторът твърдеше «стопът е ударен 05:15»,
#     тоест ДВАЙСЕТ МИНУТИ ПРЕДИ ТП1. Записът сам носи `be_since`.
#  2) СТЪЛБАТА. ТП2 не може да излезе преди ТП1, ТП3 — преди ТП2. Видимо в
#     живите данни ВСЕКИ ПЪТ: 05.08 tp1 06:35 → tp2 06:40 → tp3 06:51;
#     27.07 tp1 02:40 → tp2 03:01 → tp3 03:36.
# СЛЕД ДВЕТЕ: медиана 30 → 15 мин · p90 200 → 90 · най-лошо 226 → 110.
_a85 = open("audit_bot.py", encoding="utf-8").read()
ck("П85 BE-стопът се мери от be_since, не от отварянето",
   'tr.get("be_since")' in _a85 and 'pd.Timestamp(str(tr["be_since"])[:19])' in _a85)
ck("П85 и само когато стопът НАИСТИНА е на входа",
   'abs(float(lvl) - float(tr["entry"])) < 1e-6' in _a85)
ck("П85 стълбата се мери стъпка по стъпка",
   '_ред = {"tp2": "tp1", "tp3": "tp2"}' in _a85)
ck("П85 и стъпката гледа КОГА е пратена предната",
   "_пред = [rt for rt, k in sent_exits" in _a85)
# сребърните барове
ck("П85 одиторът дърпа и СРЕБЪРНИ барове", 'yf.download("SI=F"' in _a85)
ck("П85 всяка сделка се съди срещу СВОИТЕ барове",
   "_bars = bars5 if _сим ==" in _a85)
ck("П85 и срещу СВОЯ базис (basis за златото, basis_s за среброто)",
   '"basis" if _сим == "XAUUSD" else "basis_s"' in _a85)
# ПОВЕДЕНЧЕСКИ: помощникът наистина чете различни полета
import importlib.util as _ilu85
_sp85 = _ilu85.spec_from_file_location("ab85", "audit_bot.py")
_ab85 = _ilu85.module_from_spec(_sp85)
try:
    import sys as _s85
    _s85.modules["ab85"] = _ab85
    _sp85.loader.exec_module(_ab85)
except SystemExit:
    pass
_J85 = [{"run_utc": "2026-08-07T05:00", "basis": 55.0, "basis_s": 0.11}]
ck("П85 базисът по подразбиране е ЗЛАТНИЯТ",
   abs(_ab85._базис_към(_J85, "2026-08-07T05:00") - 55.0) < 1e-9)
ck("П85 а по искане връща СРЕБЪРНИЯ",
   abs(_ab85._базис_към(_J85, "2026-08-07T05:00", "basis_s") - 0.11) < 1e-9)
ck("П85 липсващо поле не чупи одитора",
   _ab85._базис_към(_J85, "2026-08-07T05:00", "няма_такова") == 0.0)

# ═══ П86 · СТЕПЕНУВАНЕ ПО РЕЖИМ (21.08) ═══════════════════════════════
# 🟡 `_regime` смята `below_sma200` и `low_vol` ОТ САМОТО НАЧАЛО и ги подава на
# картата — а те НИКОГА не влизаха в размера. Тоест ботът плащаше еднакво за
# половината, която печели, и за половината, която не.
# ИЗМЕРЕНО (22 години, доставената геометрия, блоков бутстрап по ден):
#   long · НАД SMA200 · ВСИЧКИ   +1.069$  [+0.206, +1.925]  74.3%  ✅ ЧИСТ ПЛЮС
#   long · НАД SMA200 · premium  +2.161$  [+0.443, +3.765]  79.5%  ✅ ЧИСТ ПЛЮС
#   long · ниска вол · premium   +3.105$  [+1.259, +4.765]  82.2%  ✅ ЧИСТ ПЛЮС
#   long · ПОД SMA200 · ВСИЧКИ   −1.248$  [−3.055, +0.587]  65.4%
# 🔴🔴 02.09 · ОБЪРНАТ. `РЕЖИМ_W_ПОД` 0.5 → 1.0. Числото зад свиването е
# НЕДОКАЗАНО: −1.248 [−3.055, +0.587] — интервалът МИНАВА ПРЕЗ НУЛАТА.
# Половин позиция се режеше по число, което не различава плюс от минус —
# същото правило, което днес поправихме в гейта: «неизмеримо» ≠ «доказано
# вредно». И същият SMA200-филтър вече е изключен в БЛОКИРАЩАТА си форма
# (би спрял 18 от 27 живи входа); режещата му форма пада по същата причина.
# ЖИВО СЛЕДСТВИЕ: първият вход след отпушването на гейта (02.09 15:32,
# «🟢 КУПИ ЗЛАТО · СРЕДЕН 5/8») излезе с «размер: ПОЛОВИНАТА · режимът е
