ck("П86 ШОРТЪТ остава непокътнат",
   lb._режим_тегло("short", {"below_sma200": True, "low_vol": True})[0] == 1.0)
# 🔴 ОБРАТНАТА ПОСОКА 2: неизвестен режим НЕ наказва
ck("П86 неизвестен режим е ПЪЛЕН размер (не гадаем)",
   lb._режим_тегло("long", {"below_sma200": None, "low_vol": None})[0] == 1.0
   and lb._режим_тегло("long", None)[0] == 1.0)
ck("П86 повреден вход не чупи бота", lb._режим_тегло("long", "боклук")[0] == 1.0)
