# ═══ П87 · ЧЕТИРИ ДЕФЕКТА В НОВАТА ВРАТА (21.08) ═══════════════════════
# Вратата, свързала гейта с картата, отвори първата златна сделка на бота —
# и след час агентите намериха в НЕЯ четири дефекта. Всичките мои.
#
# 1 · 🔴 `COOL_MIN` НЕ СЪЩЕСТВУВАШЕ — ползвах го в текст на «спряна» карта, а
#     името нямаше НИТО ЕДНО присвояване в целия проект. Заредена мина в тялото
#     на main() БЕЗ try/except: стигне ли се дотам, ботът пада с NameError,
#     трите опита падат, и рънът дава НУЛА карти — включително ИЗХОДНИ карти
#     за пари НА РИСК. Днес клонът е недостижим по аритметика; утре не е.
# 🔄 ОБЪРНАТ 25.08 · тестът заковаваше 45 минути. Числото 45 никога не е
# било мерено. МЕРЕНО на 6846 входа (ЛОНГ · клетките на гейта):
#   входовете 15-45 мин (тъкмо тези реже) +4.062$ [+1.67, +6.21] ✅
#   входовете 45-120 мин (тези пуска)     +2.435$ [+0.34, +4.31] ✅
#   над 2 часа                            +1.877$ [+0.71, +3.02] ✅
# Тоест паузата режеше НАЙ-ДОБРИТЕ. Извън гейта е нула в двете кофи.
# 🔴 01.09 · 15 → 5. МЕРЕНО: входовете, които паузата реже, са НАЙ-ДОБРИТЕ.
# ПОДЪТ от 5 обаче ОСТАВА и е важен — ботът върви на 5 мин, значи 5 не
# спира нищо, но пази от верига при по-чест рън.
ck("П87 COOL_MIN СЪЩЕСТВУВА и е число", isinstance(lb.COOL_MIN, int)
   and lb.COOL_MIN == 5)
ck("П87 паузата НЕ е нула (иначе е верига от карти)", lb.COOL_MIN >= 5)
ck("П87 COOL_FLIP_MIN също", isinstance(lb.COOL_FLIP_MIN, int) and lb.COOL_FLIP_MIN == 5)
ck("П87 и cool_ok ПОЛЗВА константите, не голи числа",
   "mins_since >= COOL_MIN" in _ИЗХОД and "mins_since >= COOL_FLIP_MIN" in _ИЗХОД)
# ЖЕЛЯЗНО: нито едно име в текстовете на «спряна» да не е недефинирано.
import ast as _a87
_т87 = _a87.parse(_ИЗХОД)
_гл87 = {n.id for x in _a87.walk(_т87) if isinstance(x, _a87.Assign)
         for n in x.targets if isinstance(n, _a87.Name)}
ck("П87 всяко ГЛАВНО име от текстовете е дефинирано",
   all(и in _гл87 for и in ("COOL_MIN", "COOL_FLIP_MIN", "REOFFER_H", "REOFFER_MAX_AGE_H")))

# 2 · 🔴 ВРАТАТА ЗАОБИКАЛЯШЕ МАКРО-ЩИТА. Петте спирачки са писани като
#     `if should_sig and <спирачка>` и стоят ПРЕДИ моя ред; аз вдигам
#     should_sig СЛЕД тях. US-щитът и стоп-пазачът оцеляват косвено
#     (`_advice_entry` сам ги връща ok=False), НО `cq_block` НЕ Е в
#     сигнатурата му. ДОКАЗАНО: срезът, пуснат с cq_block=True → картата
#     тръгваше по средата на макро събитие, когато спредът се разширява.
ck("П87 вратата пази МАКРО-ЩИТА", "and not cq_block" in _ИЗХОД)
ck("П87 и US-щита за шорта", 'not (shield and new_dir == "short")' in _ИЗХОД)
# 🔄 ОБЪРНАТ 25.08 · тестът търсеше ЗАКОВАНОТО «< 2». Прагът на пазача
# стана 1 (мерено) и тази врата съдеше по РАЗЛИЧНО число от всички
# останали — щеше да пуска карта СЛЕД стоп, който другите смятат за
# спиращ. Двете части на бота пак щяха да се карат за едно събитие.
# 🔴 01.09 · ОБЪРНАТ. Гаранцията «двете части съдят по ЕДНА константа»
# ОСТАВА — само четенето вече минава през давността на пазача.
ck("П87 и стоп-пазача — по СЪЩАТА константа, не по заковано число",
   "_пазач_n(guard, new_dir, now_utc) < ПАЗАЧ_СТОПОВЕ)" in _ИЗХОД)
_РГ87 = "guard" + chr(91) + chr(94) + chr(10) + chr(93) + "{0,30}[<>]=?" + chr(92) + "s*[0-9]"
ck("П87 никъде не е останал ЗАКОВАН праг на пазача",
   not __import__("re").search(_РГ87, _ИЗХОД))
ck("П87 а спреният повод се КАЗВА, не се губи мълчаливо",
   "поводът от гейта е спрян от щит" in _ИЗХОД)

# 3 · 🔴 КАРТАТА ЛЪЖЕШЕ ЗА ПРИЧИНАТА. И трите прехода в целия дневник са от
#     by='стара цена' към by='клетка' — тоест ЖИВАТА ЦЕНА СЕ ВЪРНА, а не
#     макрото се подреди. Кръстосано: by=='стара цена' ⟺ spot is None в
#     937 от 937 записа. Поводът е законен; текстът описваше друго събитие.
ck("П87 при върната цена картата казва ИМЕННО това",
   "ЖИВАТА ЦЕНА СЕ ВЪРНА" in _ИЗХОД)
ck("П87 а при истинска смяна — назовава СТАРАТА причина",
   'ГЕЙТЪТ СТАНА ЗЕЛЕН (беше «{_пред_by' in _ИЗХОД)
ck("П87 и причината се ПОМНИ между ръновете", 'meta["adv_ok_by_посл"]' in _ИЗХОД)

# 4 · 🔴 ЗНАМЕТО ИЗГАРЯШЕ БЕЗ ДОСТАВКА. Пишеше се БЕЗУСЛОВНО — не питаше нито
#     дали картата е тръгнала, нито дали е ДОСТАВЕНА. Спре ли я щит или върне
#     ли Телеграм HARD_FAIL, поводът изгаряше ЗАВИНАГИ. А това е ЕДИНСТВЕНАТА
#     врата между гейта и картата — точно тя отвори първата златна сделка.
ck("П87 знамето се вдига САМО след потвърдена доставка",
   '(not _гейт_обрат) or ("signal" in sent_tags) or (not _adv_ok)' in _ИЗХОД)
ck("П87 и запазването се КАЗВА", "поводът от гейта се ПАЗИ за следващия рън" in _ИЗХОД)
# 🔴 ОБРАТНАТА ПОСОКА: падането ДА→НЕ трябва да се пише ВИНАГИ, иначе
# обратът не може да се засече повторно.
ck("П87 падането на гейта се записва винаги (иначе обратът се губи)",
   "or (not _adv_ok)" in _ИЗХОД)

# ═══ П88 · ЧЕРНАТА КУТИЯ · «защо мълчах в 14:37» вече има отговор ═══════
# A · 🔴 ПОЩАТА ТРИЕШЕ ОСИРОТЯЛА `signal` КАРТА БЕЗМЪЛВНО. Изхвърлянето е
#     ПРЕДИ цикъла за пращане → никога не стига до `statuses.append`, а
#     дедупът точно отдолу СЕ обажда. Междувременно на собственика вече е
#     отпечатано «signal НЕ пратен … (ще опита пак)» — а втори опит НЯМА:
#     щом реофер-вратите са затворени, картата не се регенерира и изчезва.
_д88 = _P(_tf.mkdtemp())
(_д88 / "outbox.jsonl").write_text(json.dumps(
    {"tag": "signal", "text": "🟢 ЗЛАТО покупка 4621.25",
     "first_ts": "2026-08-21T18:00:00", "attempts": 1}), encoding="utf-8")
