ck("П88 и казва, че НЯМА да се опита пак", any("НЯМА да се опита пак" in x for x in _ст88))
ck("П88 и назовава ВИДА на картата", any("signal" in x for x in _ст88))
# 🔴 ОБРАТНАТА ПОСОКА: карта, която Е регенерирана този рън, НЕ се хвърля
_д88б = _P(_tf.mkdtemp())
(_д88б / "outbox.jsonl").write_text(json.dumps(
    {"tag": "signal", "text": "стар текст", "first_ts": "2026-08-21T18:00:00",
     "attempts": 1}), encoding="utf-8")
_ст88б = []
lb._outbox_flush(_д88б, [("signal", "нов текст")], _ст88б, dry=True)
ck("П88 регенерирана карта НЕ се обявява за осиротяла",
   not any("осиротели" in x for x in _ст88б))
ck("П88 «ще опита пак» вече зависи от това дали ИМА как",
   "НЯМА да опита пак — вратите са затворени" in _ИЗХОД)

