# 🔄 ОБЪРНАТ 25.08 · ТЕСТЪТ КАЗВАШЕ «таванът НЕ е пипан». Основанието му беше
# реплей, който отваряше MAX_AGE ГЛОБАЛНО: +399 карти = 21/ден = спам.
# Новият реплей (същият журнал, 4357 ръна, сверен байт-в-байт с живия
# last_sent.json: реплика '1|long:premium' == last_sent '1|long:premium')
# мери таван ПО КЛЕТКА, а не глобално:
#     v14.2 както беше                18 карти = 0.81/ден
#     + часовете 0-23                 21       = 0.94
#     + гейт-вратата (v15.0)          23       = 1.03
#     + прагът по клетка (v15.4)      25       = 1.12
#     MAX_AGE=24 ГЛОБАЛНО             31       = 1.39   ← ТОВА пазеше тестът
#     ВСИЧКО отворено                388       = 17.37  ← ТОВА е спамът
# А пределните входове по клетка (22г лента, доставената геометрия):
#     ЛОНГ · fresh  +12ч  +3.740$  [+0.012, +6.620]  ✅ ЧИСТ ПЛЮС
#     ЛОНГ · fresh  +18ч  +3.148$  ·  +24ч  +1.676$  (положителни оценки)
#     ЛОНГ · day1   +12ч  +0.092$ · +18ч −1.651$ · +24ч +0.453$  РАЗБЪРКАНО
#     ЛОНГ · stale  +12ч  −1.599$  ·  ШОРТ +12ч  −0.279$
# Тоест `fresh` е положителен на ВСЕКИ хоризонт; никоя друга клетка не е.
# Затова таванът се вдига САМО там. Тестът вече пази ТОВА.
# 🔄 ОБЪРНАТ · основата 12ч → 240ч (виж мярката при О4). Клетъчната
# СТЪЛБА остава — `fresh` пак получава по-широк таван от останалите.
# 🔴🔴 01.09 · ОБЪРНАТ И НАПРАВЕН ПО-СИЛЕН, НЕ ИЗТРИТ.
# Дотук този блок замразяваше СТЪЛБАТА ПО КЛЕТКА (long·fresh широк таван,
# всичко друго базовия). Стълбата е ПРЕМАХНАТА нарочно: и двата тавана са
# 0 = БЕЗ ТАВАН, защото таванът беше МОЯТА спирачка и точно той уби
# картите (сетъпът е на 258ч, правилото пускаше до 240ч), а мереното казва,
# че «без таван» бие по ВСИЧКО наведнъж: +120$/год [+58,+182], просадка
# 301$ — най-много пари, най-висока ДОЛНА граница И най-малка просадка.
#
# Тестът вече проверява ДВЕ неща вместо едно:
#   1) в отпушен режим НИЩО не се спира по възраст
#   2) СПИРАЧКИ=МЕРЕНИ НАИСТИНА връща стълбата — ИЗПЪЛНЕНО, не изчетено
# Досега пътят назад беше само обещание в коментар.
# 🔴 01.09 · ОБЪРНАТ ВТОРИ ПЪТ. Сутринта: «нищо не спира по възраст».
# По обяд: точно това произвеждаше «закъснелите неща» — сетъп на 274 часа,
# предлаган на всеки два часа. Стълбата по клетка СЕ ВРЪЩА, но по-широка от
# сутринта: 48ч базово, 96ч за пресния лонг (беше 240/480).
ck("П90 всяка клетка пак има КРАЕН таван",
   all(0 < lb._max_age_h(_д, _н) < float("inf")
       for _д in ("long", "short", None, "")
       for _н in (0, 1, 2, 3, 5, 9)))
