ck("П101 отворена сребърна сделка СЕ ДОСЛЕДЯВА",
   "_сребро_сирак = (not СРЕБРО) and s_tr_f.exists()" in _ИЗХОД
   and "доследявам я до изход" in _ИЗХОД)
