# ═══ П96 · ПАЗАЧЪТ СЪДИ КАТО КАРТАТА ═════════════════════════════════════
# 🔴 25.08 · СЛУЧИ СЕ ЖИВО ДНЕС и струва цял търговски следобед:
#   08:22 КУПИ 4630.54 → ТП1 +12.14$ · ТП2 +12.14$ · остатък излиза 4627.81
#   КАРТАТА (правило «взета ли е поне една цел», live_bot.py:2130):
#       «✅ НУЛА · стопът беше на входа» — ВЯРНО, сделката е ПЕЧЕЛИВША
#   ПАЗАЧЪТ (правило «колко далеч е филът»): |4627.81−4630.54| = 2.73$ > 0.05
#       → преброи го за ИСТИНСКИ СТОП → втори за деня → «спирам до утре»
# Двете части на бота се караха за едно и също събитие. Разминаването се
# появява точно когато филът ГАПНЕ покрай входа — при бърз пазар, когато
# сделките са най-важни.
def _п96(kind, cum_hit, px, entry):
    """Същата аритметика като в live_bot.py — изпълнена, не грепната."""
    _вц = any(cum_hit.get(k) for k in ("tp1", "tp2", "tp3"))
    if kind == "sl" and not _вц and abs(px - entry) > 0.05:
        return True
    return False
