ck("П96 стоп след САМО ТП1 не се брои", _п96("sl", {"tp1": True}, 4636.0, 4636.19) is False)
ck("П96 стоп на самия вход без цели не се брои (гап)",
   _п96("sl", {}, 4640.15, 4640.17) is False)
ck("П96 целите не се броят за стоп", _п96("tp1", {"tp1": True}, 4643.69, 4636.19) is False)
