# ═══ П97 · «ВИЖДАМ, НО НЕ ПРЕДЛАГАМ» СПИРА ДА Е ТАПЕТ ════════════════════
# 🔴 25.08 · ПРЕБРОЕНО от живия sent_log за деня: 90 карти общо, от които
# «спряна:long» = 72 — всичките с една и съща причина, само часът расте.
# Поправката ѝ (от 0 излизания за целия ѝ живот) я направи достижима и тя
# веднага отиде в другата крайност. Тапетът прави истинските карти невидими.
from datetime import datetime as _dt97, timedelta as _td97
def _п97(meta, now, повод):
    _пвд = str(повод).split("·")[0].split(",")[0].strip()[:40]
    _пс = meta.get("спряна_посл") or {}
    ок = True
    if _пс.get("повод") == _пвд and _пс.get("utc"):
        _м = (_dt97.fromisoformat(now) - _dt97.fromisoformat(_пс["utc"])).total_seconds() / 60.0
        ок = _м >= lb.СПРЯНА_ПОВТОР_Ч * 60
    if ок:
        meta["спряна_посл"] = {"повод": _пвд, "utc": now}
    return ок
_m97 = {}
_t97 = _dt97.fromisoformat("2026-08-25T09:00")
_бр97 = sum(1 for i in range(96)
            if _п97(_m97, (_t97 + _td97(minutes=5 * i)).isoformat(timespec="minutes"),
                    "сетъпът е на 109ч, правилото пуска до 12ч (клетка stale)"))
ck(f"П97 96 ръна с ЕДНА причина дават {_бр97} карти вместо 96", _бр97 <= 6)
# 🔴 ОБРАТНАТА ПОСОКА: НОВА причина минава ВЕДНАГА — иначе ограничителят
# заглушава информация, а не повторение (същият грях като алармата на 24.08)
_m97b = {}
_t97b = _dt97.fromisoformat("2026-08-25T09:00")
_р97 = [_п97(_m97b, (_t97b + _td97(minutes=5 * i)).isoformat(timespec="minutes"), _пв)
        for i, _пв in enumerate(["сетъпът е на 109ч", "сетъпът е на 109ч", "сетъпът е на 109ч",
                                 "ре-влизане в пауза", "ре-влизане в пауза",
                                 "стоп-пазач · 2 стопа днес"])]
ck("П97 НОВА причина минава ВЕДНАГА, без чакане",
   _р97 == [True, False, False, True, False, True])
ck("П97 ограничителят си казва, че е задържал", "се повтаря — същият повод" in _ИЗХОД)
ck("П97 има път назад (СПРЯНА_ПОВТОР_Ч от средата)",
   'os.environ.get("СПРЯНА_ПОВТОР_Ч"' in _ИЗХОД)
_с97 = lb.СПРЯНА_ПОВТОР_Ч
try:
    lb.СПРЯНА_ПОВТОР_Ч = 0.0
    _m97c = {}
    ck("П97 с 0 се връща СТАРОТО поведение (карта на всеки рън)",
       all(_п97(_m97c, (_t97 + _td97(minutes=5 * i)).isoformat(timespec="minutes"), "един повод")
           for i in range(8)))
finally:
    lb.СПРЯНА_ПОВТОР_Ч = _с97
