# частичен дневен бар). ЦЕНАТА, мерена от 3718 живи ръна:
#     гейтът е зелен  fresh 116/261 = 44.4%   ·   day1 0/46 = 0.0%
# Едно такова мигване превръща търгуем сетъп в НЕтъргуем, безшумно.
# ПРАВИЛОТО: в рамките на един календарен ден стрийкът може да падне на НУЛА
# (подреждането се е счупило — истинско събитие), да остане или да порасне.
# НО не може да падне на по-малко НЕНУЛЕВО число.
def _п95(meta, date, посока, streak_n):
    """Същата аритметика като в live_bot.py — изпълнена, не грепната."""
    if lb.СТРИЙК_ПАЗАЧ and посока:
        _сп = meta.get("стрийк_ден") or {}
        _пред = _сп.get(посока) if _сп.get("дата") == date else None
        if _пред is not None and 0 < streak_n < int(_пред):
            streak_n = int(_пред)
        _нов = dict(_сп) if _сп.get("дата") == date else {"дата": date}
        _нов["дата"] = date
        _нов[посока] = max(int(_нов.get(посока) or 0), int(streak_n)) if streak_n else 0
        meta["стрийк_ден"] = _нов
    return streak_n
def _пуск95(стъпки, посока="long"):
    m = {}
    return [_п95(m, д, посока, с) for д, с in стъпки]
ck("П95 истинският случай 21.08 (2→1 за 7 мин) се ДЪРЖИ",
   _пуск95([("2026-08-21", 2), ("2026-08-21", 1)]) == [2, 2])
# 🔴 ОБРАТНАТА ПОСОКА — четири случая, които ТРЯБВА да минат
ck("П95 счупено подреждане (2→0) МИНАВА — това е истинско събитие",
   _пуск95([("2026-08-21", 2), ("2026-08-21", 0)]) == [2, 0])
ck("П95 растеж (2→3) МИНАВА", _пуск95([("2026-08-21", 2), ("2026-08-21", 3)]) == [2, 3])
ck("П95 НОВ ДЕН (3→1) МИНАВА — там 1 е законно",
   _пуск95([("2026-08-21", 3), ("2026-08-22", 1)]) == [3, 1])
ck("П95 нова поредица след прекъсване (2→0→1) МИНАВА",
   _пуск95([("2026-08-21", 2), ("2026-08-21", 0), ("2026-08-21", 1)]) == [2, 0, 1])
ck("П95 двете посоки се помнят ПООТДЕЛНО",
   _пуск95([("2026-08-21", 4), ("2026-08-21", 1)], "short") == [4, 4]
   and _пуск95([("2026-08-21", 4), ("2026-08-21", 1)], "long") == [4, 4])
ck("П95 пазачът НЕ мълчи — казва какво е задържал",
   "стрийкът щеше да падне" in _ИЗХОД and "ревизия на данните" in _ИЗХОД)
ck("П95 има път назад (СТРИЙК_ПАЗАЧ от средата)",
   'os.environ.get("СТРИЙК_ПАЗАЧ"' in _ИЗХОД)
# 🔴 И ЖЕЛЯЗНОТО: с ИЗКЛЮЧЕН пазач старото поведение се връща ТОЧНО
_ст95 = lb.СТРИЙК_ПАЗАЧ
try:
    lb.СТРИЙК_ПАЗАЧ = False
    ck("П95 изключен пазач → старото поведение (2→1 минава)",
       _пуск95([("2026-08-21", 2), ("2026-08-21", 1)]) == [2, 1])
finally:
    lb.СТРИЙК_ПАЗАЧ = _ст95
ck("П95 пазачът е ВКЛЮЧЕН по подразбиране", lb.СТРИЙК_ПАЗАЧ is True)

# ═══ П93 · СТЕПЕНТА СЕ ВИЖДА НА КАРТАТА ══════════════════════════════════
# 🔴 25.08 · Собственикът я иска дословно («ПРОСТО ДА СТЕПЕНУВА СИГНАЛИТЕ»),
# ботът я СМЯТА — и я ИЗХВЪРЛЯШЕ. Доказано с AST върху самата функция:
# 12 от 28 аргумента на `_sig_msg` не се четат НИКЪДЕ, сред тях `tier_name`,
# `score` и `agree_n`. Картата за ПРЕМИУМ и картата за СРЕДЕН се различаваха
# с НУЛА знака — при 6× разлика в размера на позицията.
_л93 = lb._levels(4365.2, "long")
_к93 = lb._sig_msg("long", 6, 7, "СИЛЕН", {"mid": 4365.2}, 4365.0, "2026-08-11T11:15",
                   _л93, 4365.2, "ДА — пресен клас",
                   {"миньори": True, "долар": True, "лихви": False}, 1,
                   {"vol_rank": 0.5}, {}, 5000, 2.0, adv_ok=True)
_п93 = lb._sig_msg("long", 8, 8, "ПРЕМИУМ", {"mid": 4365.2}, 4365.0, "2026-08-11T11:15",
                   _л93, 4365.2, "ДА — доларът и лихвите падат",
                   {"миньори": True, "долар": True, "лихви": True}, 3,
                   {"vol_rank": 0.5}, {}, 5000, 2.0, adv_ok=True)
ck("П93 степента е на картата", "СИЛЕН" in _к93 and "ПРЕМИУМ" in _п93)
ck("П93 и сборът е до нея", "6/8" in _к93 and "8/8" in _п93)
ck("П93 двете карти вече СЕ РАЗЛИЧАВАТ (беше нула знака разлика)",
   _к93.splitlines()[0] != _п93.splitlines()[0])
ck("П93 степента е на ПЪРВИЯ ред, там където се чете",
   "СИЛЕН" in _к93.splitlines()[0] and "ПРЕМИУМ" in _п93.splitlines()[0])
# 🔴 ОБРАТНАТА ПОСОКА: липсва ли степен, картата НЕ бива да гърми и НЕ бива
# да измисля. И НЕ бива да твърди съгласие, което не може да преброи —
# ОДИТ-45г доказа, че «/7» е невярно, защото рамките са копия.
_б93 = lb._sig_msg("long", None, None, None, {"mid": 4365.2}, 4365.0, "2026-08-11T11:15",
                   _л93, 4365.2, "ДА", {"миньори": True, "долар": True, "лихви": False},
                   1, {"vol_rank": 0.5}, {}, 5000, 2.0, adv_ok=True)
ck("П93 без степен картата не гърми и не измисля",
   "КУПИ" in _б93 and "None" not in _б93 and "/8" not in _б93)
ck("П93 картата НЕ твърди съгласие, което не може да преброи",
   "отчета" not in _к93 and "/7" not in _к93)
# 🔴 ПРОВЕРЯВА СЕ С AST, не с греп: `_съгласни(board, …)` съществува
# ЗАКОННО в друга карта, където `board` Е аргумент. Тук се пита дали
# _sig_msg чете име, което НЕ ѝ е подадено — това е класът дефект,
# който `try/except Exception` глътва мълчаливо.
import ast as _a93
for _fn93 in _a93.walk(_a93.parse(_ИЗХОД)):
    if isinstance(_fn93, _a93.FunctionDef) and _fn93.name == "_sig_msg":
        _имена93 = {a.arg for a in _fn93.args.args} | {a.arg for a in _fn93.args.kwonlyargs}
        _мест93 = set()
        for _n93 in _a93.walk(_fn93):
            if isinstance(_n93, _a93.Name) and isinstance(_n93.ctx, _a93.Store):
                _мест93.add(_n93.id)
            if isinstance(_n93, (_a93.FunctionDef, _a93.Lambda)) and _n93 is not _fn93:
                _мест93 |= {a.arg for a in _n93.args.args}
        _чуждо93 = sorted({n.id for n in _a93.walk(_fn93)
                           if isinstance(n, _a93.Name) and isinstance(n.ctx, _a93.Load)
                           and n.id not in _имена93 and n.id not in _мест93
                           and n.id not in dir(lb) and n.id not in dir(__builtins__)})
        ck(f"П93 _sig_msg не чете име, което не ѝ е дадено ({_чуждо93[:3]})",
           not _чуждо93)
        break
# 🔴 И ПРАВИЛОТО ЗА ТЕЛЕФОН ОСТАВА ПО-ВАЖНО от допълнението
ck("П93 картата се събира в тавана", len([x for x in _к93.splitlines() if x.strip()]) <= 7)

# ═══ П94 · РАЗМЕРЪТ НА КАРТАТА Е ИСТИНСКИЯТ ══════════════════════════════
# 🔴 25.08 · `_сила` свиваше ДЕВЕТ реални множителя до ПЕТ надписа чрез
# «най-близката красива дроб». ИЗПЪЛНЕНО върху всичките реални множители:
#     0.0825 ( 8.2%) → «⅙ от пълния» = 16.7%  ← обявяваше 2.02× ПОВЕЧЕ
#     0.2500 (25.0%) → «⅓ от пълния» = 33.3%  ← обявяваше 1.33× ПОВЕЧЕ
# Собственикът СМЯТА позицията си от тази дроб. Прочете ли «⅙», а ботът да е
# сметнал 1/12, той влиза с ДВОЕН риск спрямо замисленото.
_ДЯЛ94 = {"⅙ от пълния": 1/6, "⅓ от пълния": 1/3, "½ от пълния": 0.5,
          "⅔ от пълния": 2/3, "пълен размер": 1.0, "не влизам": 0.0}
_МН94 = [0.0825, 0.165, 0.1675, 0.25, 0.33, 0.335, 0.5, 0.67, 1.0]
for _м94 in _МН94:
    _е, _д, _дял = lb._сила(_м94)
    _обяв = _ДЯЛ94.get(_дял)
    if _обяв is None:
        import re as _re94
        _мм = _re94.search(r"(\d+)%", _дял)
        _обяв = (float(_мм.group(1)) / 100.0) if _мм else None
    ck(f"П94 при {100*_м94:.1f}% картата обявява истината (казва «{_дял}»)",
       _обяв is not None and abs(_обяв - _м94) <= 0.011)
ck("П94 нулата си остава ясна", lb._сила(0.0)[1] == "НУЛА")
ck("П94 думите са КОЛИЧЕСТВА, не увереност",
   {lb._сила(m)[1] for m in _МН94} <= {"ВСИЧКО", "МНОГО", "ПОЛОВИНАТА", "ЛЕКО", "ЕДВА"})
# 🔴 ОБРАТНАТА ПОСОКА: красивата дроб ОСТАВА там, където е ВЯРНА
ck("П94 вярната дроб не е заменена с процент",
   lb._сила(0.5)[2] == "½ от пълния" and lb._сила(1/3)[2] == "⅓ от пълния")

