#     200/200 ДОСТАВЕНА  ТП1 75п  удря 71.2%  +0.612$/сделка
#     150/150            ТП1 56п  удря 72.6%  +0.304$
#     100/100            ТП1 38п  удря 70.5%  −0.096$
# ⚠️ пропорционалното свиване НЕ вдига ударите (стопът се свива заедно с целта);
