# ═══ П107 · ПАЗАЧЪТ С ДАВНОСТ + ОТПУШЕНИЯТ МОЗЪК ════════════════════════
# 🔴 01.09 · ПРЕБРОЕНО в живия дневник: от последните 1200 ръна 998 са
# спрени от «стоп-пазач» = 83%. На 28.08: 205 ръна, 0 сигнала, 203 пазач.
# Един стоп заключваше ЦЯЛАТА посока до края на деня — стоп в 00:16
# убиваше 24 часа. Мерено по ЧАСОВЕ (две независими преработки, ЛОНГ):
#   0-2ч −2.706$ ⚪ / −3.204$ [−6.33,−0.09] 🔴 · 2-4ч −1.665$ / −2.514$ ⚪
#   4-8ч +6.356$ [+2.63,+9.39] ✅ / +1.107$ ⚪ · 8-24ч +3.707$ / +2.883$ ⚪
# Разминават се по РАЗМЕР, съвпадат по ЗНАК и по ЗАВОЙ → прозорец 4 часа.
import datetime as _D107

_N107 = "2026-09-01T12:00"


def _g107(часа_назад, брой=1, ключ="long"):
    _т = (_D107.datetime.fromisoformat(_N107)
          - _D107.timedelta(hours=часа_назад)).isoformat(timespec="minutes")
    return {ключ: брой, ключ + "_t": _т}


