# 🔴 01.09 · Собственикът: «искам новините да спрат да се мятат и да се дават
# важни и по-добре». ПРЕБРОЕНО в живия дневник: ОСЕМ бележки за целия период
# и ВСИЧКИТЕ ОСЕМ са ЕДНО събитие (FOMC Джексън Хоул), различни само по
# числото: след 15ч28 · 13ч28 · 11ч28 · 9ч24 · 7ч24 · 5ч24 · 3ч24 · 1ч24.
# Аритметиката: 15 часа напред ÷ повторение на 2ч = 8 карти.
# ФИЛТЪРЪТ ПО ВАЖНОСТ НЕ Е ПРОБЛЕМЪТ — календарът дава 5 събития, всичките
# critical/high. Проблемът е ритъмът.
_EVT108 = "2026-09-04T13:30:00.000Z"
_CQ108 = {"events": [{"name": "NFP — Доклад за заетостта", "dt": _EVT108, "impact": "high"}]}
_КРАЙ108 = pd.Timestamp(_EVT108).tz_localize(None)


def _сим108(модул):
    """Върти бота на 5 мин от −20ч до събитието и брои КОЛКО КАРТИ излизат."""
    _мета = {}
    _карти = []
    for _i in range(int(20 * 60 / 5), -1, -1):
        _сега = (_КРАЙ108 - pd.Timedelta(minutes=5 * _i)).isoformat()
        _нд = модул._news_due(_CQ108, _сега, _мета)
        if _нд:
            _карти.append((round(_нд[2], 1), _нд[4]))
            _мета["новина"] = {"кой": _нд[3], "utc": _сега,
                               "етап": (_нд[5] if len(_нд) > 5 else None)}
    return _карти


