# ═══ П110 · ЗАДУШВАЧЪТ КЛЮЧОВА ПО ВИД, НЕ ПО ТЕКСТ ══════════════════════
# 🔴 01.09 · ВИДЯНО ЖИВО: картата «⏸ ВИЖДАМ ПОКУПКА · но не я давам» излезе
# в 05:36 · 05:41 · 05:46 · 05:51 · 06:02 · 06:06 — ШЕСТ пъти за половин час,
# при праг СПРЯНА_ПОВТОР_Ч = 2 ЧАСА.
# ПРИЧИНАТА: ключът беше самият ТЕКСТ на повода, а поводът носи число, което
# расте всеки рън: «1.5ч от последната карта» → «1.6ч…» → друг ключ всеки път.
# Дефектът е стар, но МОИТЕ промени го изкараха наяве: докато пазачът спираше
# 83%, активният повод беше «стоп-пазач» (без число → стабилен ключ); щом
# пазачът падна, активен стана поводът с растящия час.
_РАСТЯЩИ110 = ["%.1fч от последната карта, трябват 2ч (клетка stale)" % _x
               for _x in (0.1, 0.6, 1.5, 1.9)]
ck("П110 растящо число дава ЕДИН И СЪЩ ключ",
   len(set(lb._вид_повод(_t) for _t in _РАСТЯЩИ110)) == 1)
ck("П110 и този ключ НЕ съдържа цифри",
   not any(c.isdigit() for c in lb._вид_повод(_РАСТЯЩИ110[0])))

# 🔴 ОБРАТНАТА ПОСОКА · РАЗЛИЧНИ поводи трябва да останат РАЗЛИЧНИ, иначе
# задушвачът ще глътне и втора, СЪВСЕМ ДРУГА причина — тоест ще заглуши
# информация вместо повторение.
_РАЗЛИЧНИ110 = ["сетъпът е на 270ч, правилото пуска без таван",
                "стоп-пазач · 1 стоп в тази посока · вдига се след 137 мин",
                "таванът на сделките е пълен: 3 от 12 отворени",
                "1.5ч от последната карта, трябват 2ч (клетка stale)"]
ck("П110 четири РАЗЛИЧНИ повода дават четири РАЗЛИЧНИ ключа",
   len(set(lb._вид_повод(_t) for _t in _РАЗЛИЧНИ110)) == 4)
ck("П110 празно/None не гърми",
   lb._вид_повод(None) == "" and lb._вид_повод("") == "")

# сравнението и записът ползват ЕДНА И СЪЩА функция — иначе се разминават
ck("П110 сравнението минава през вида",
   "_вид_повод(_пс.get(" in _ИЗХОД and "_вид_повод(_пвд)" in _ИЗХОД)
ck("П110 записът също минава през вида",
   '"повод": _вид_повод(str(_спрян[0]))' in _ИЗХОД)
# суровото ключоване е позволено САМО вътре в самата _вид_повод
ck("П110 никъде не е останало ключоване по СУРОВ текст",
   'str(_спрян[0]).split("·")' not in _ИЗХОД
   and _ИЗХОД.count('.split("·")[0].split(",")[0]') == 1)

