# ═══ П112 · ФАНТОМНИЯТ СТОП ОТ ЗАСТОЯЛИЯ БАЗИС ══════════════════════════
# 🔴🔴 01.09 · Собственикът: «беше объркан пазачи с някъв уж стоп лос хит,
# като такова нещо никога не е имало». ПРАВ Е БИЛ. Възстановени 9314 ръна от
# git; от 12 записани стопа в златния леджър ТРИ са фантоми по цена:
#   25.08 07:11 запас +0.262$ · 25.08 08:21 +0.141$ · 27.08 23:31 +0.758$
# ВЕРИГАТА: барът е стар (медиана 10 мин) → базис = фючърс отпреди 10 мин
# МИНУС спот сега → BASIS_ALPHA=0.25 добавя още ~15 мин лаг → застоялият
# базис се вади от ПРЕСНИ барове → lo = Low − basis → sl_hit.
# ИЗМЕРЕНО на 6340 ръна: |грешка| > 2$ в 43.0%, > 4$ в 16.3%, при стоп 20$;
# корелация с 15-минутното движение r = −0.769 → при падане грешката е
# +3.349$ и ЛОНГ стопът пали рано. 11 от 12 стопа са ЛОНГ в падащ пазар.
# За фантом №5 живият спот за 70 мин и 15 проби НИКОГА не е бил по-близо
# от 3.565$ до стопа. Решил е базисът, не пазарът.
