# ═══ П113 · ПИТАШ БОТА И ТОЙ ОТГОВАРЯ ═══════════════════════════════════
# 🔴 01.09 · Собственикът: «искам всичко ясно и точно и ПОСТОЯННО, и да не се
# премълчава нищо, но без спам — всяка сделка и всичко да се вижда».
# Картата «КЪДЕ СМЕ» съществуваше от седмици, но се пускаше САМО с флаг от
# командния ред — тоест беше на практика НЕДОСТЪПНА за него. Сега, когато
# ботът вече ЧЕТЕ, питането е възможно. Това е по-добро от още една
# автоматична карта: няма спам, а отговорът идва точно когато трябва.
import os as _os113

_ЧАТ113 = str(_os113.environ.get("TELEGRAM_CHAT_ID") or "")


def _q113(t, ch=None, пре=False):
    return {"текст": t, "чат": _ЧАТ113 if ch is None else ch, "препратен": пре}


for _т113 in ("къде сме", "Статус", "какво става?", "сделки?", "?"):
    ck("П113 «%s» се разпознава като питане" % _т113, lb._е_питане(_q113(_т113)) is True)

