# ═══ П114 · ДНЕВНИКЪТ ЗАПИСВА ПОСОКАТА ══════════════════════════════════
# 🔴🔴 01.09 · Собственикът: «в момента е ШОРТ, който пак не знам защо не го
# каза ботът — той беше виден». Опитах да проверя от дневника какво Е ВИЖДАЛ
# мозъкът и НЕ МОЖАХ: полето  е None във ВСИЧКИТЕ 40 записа.
# ПРИЧИНАТА: дневникът пишеше , а това е ОПИСАТЕЛЕН ЕТИКЕТ
# («ОБРАН ВРЪХ»), не посока. Истинската посока е булевото  и то НЕ СЕ
# ПИШЕШЕ. Същият дефект вече ме подведе веднъж днес — заради него бектестът
# обърна 48% от сделките.
