# ═══ П115 · «БЕЗ ЧИСЛА НЯМА ВХОД» беше ОБЕЩАНИЕ, не правило ══════════════
# 🔴🔴 01.09 · ОДИТ-49 (ред 265) обещава дословно «БЕЗ ЧИСЛА НЯМА ВХОД».
# ИЗПЪЛНЕНО, не прочетено — ето какво правеше кодът:
#     stats = {}                        → НЕ   ✓
#     stats = {"fresh": {}}             → ДА   ✗
#     stats = {"fresh": {"long": {}}}   → ДА   ✗
#     n=5,  нето −50$                   → ДА   ✗
#     n=99, нето −50$                   → ДА   ✗  (под собствения праг MIN_N=100)
# ПРИЧИНАТА: и двете блокиращи проверки са с формата
#     if seg["n"] >= MIN_N and (seg["net"] <= 0 or _noise(seg)):  → НЕ
# тоест съдят САМО когато ИМА достатъчно числа. Няма ли ги — МИНАВА.
# MIN_N работеше ТОЧНО ОБРАТНО на принципа, който описва.
# А това е ЕДИНСТВЕНАТА врата, която решава дали да се отвори сделка.
#
# ЛЕКЪТ НЕ Е ДА СЕ РЕЖЕ (собственикът иска бота отпушен, а стягането тук би
# затворило гейта точно в най-редките клетки). Картата ГО КАЗВА.
import copy as _cp115
import json as _js115
import io as _io115

_R115 = _js115.load(_io115.open("backtest_stats.json", encoding="utf-8"))

# ── с ИСТИНСКИТЕ числа поведението НЕ се мени (иначе съм счупил бота) ──
for _д115, _с115 in (("long", 1), ("long", 2), ("long", 5), ("short", 1)):
    _т115, _ок115 = lb._advice_entry(_д115, _с115, _R115, None, False, 0)
    ck("П115 истинските числа минават без надпис (%s/%d)" % (_д115, _с115),
       "БЕЗ измерени числа" not in _т115)

# ── празна клетка: МИНАВА, но си го КАЗВА ──
_b115 = _cp115.deepcopy(_R115)
_b115["fresh"]["long"]["fresh"] = {}
_т115b, _ок115b = lb._advice_entry("long", 2, _b115, None, False, 0)
ck("П115 празна клетка пак пуска (не режем)", _ок115b is True)
ck("П115 но КАЗВА, че няма числа", "БЕЗ измерени числа" in _т115b)

# ── тънка клетка: същото, и казва ТОЧНИЯ брой ──
_b115c = _cp115.deepcopy(_R115)
_b115c["fresh"]["long"]["fresh"] = {"win": 77.2, "net": 2.01, "n": 7}
_т115c, _ок115c = lb._advice_entry("long", 2, _b115c, None, False, 0)
ck("П115 тънка клетка (n=7) също се обявява",
   "БЕЗ измерени числа" in _т115c and "7 от нужните 100" in _т115c)

