# ═══ П116 · ДВЕТЕ СТРАНИ СЕ ВИЖДАТ ══════════════════════════════════════
# 🔴 01.09 · Собственикът: «искам да си има шортове — когато е добър входът;
# човек си преценява» и «има бол места по над 100 пипса».
# НАМЕРЕНО: `_scores` връща ls И ss за ВСЯКА от седемте рамки, на ВСЕКИ рън —
# а `_resolve` връща само max(ls, ss) и губещата страна СЕ ИЗХВЪРЛЯ.
# Речникът `превеси` пазеше дори РАЗЛИКАТА |ls−ss|, но не и двете числа.
# Тоест ботът смяташе шорт-резултата стотици пъти на ден и НИКОГА не го
# показваше — човекът виждаше «нагоре» до мига, в който стане «надолу».
